INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time, language)
VALUES ('ea728084-f3fe-4ea8-9d32-83653bee2580',
        true,
        'Khúc ca đoạt hồn giữa đêm khuya',
        '<p>Hai cô gái đứng ở mép tầng cao nhất của tòa nhà Y Garden, hát và nói những lời của triều đại cổ đại, so sánh mình với những quý phi trong cung đình cổ đại, hoàn toàn không để tâm đến tình cảnh nguy hiểm của mình.</p>
        <p>Hai cô gái này chính là Băng Băng và Hứ Tuyết trong phòng ký túc xá nữ 411. Họ trang điểm đậm, mặc đồ, dưới ánh trăng trông rất quyến rũ và nổi bật. Bên cạnh họ, vài bảo vệ đang từ từ tiếp cận.</p>
        <p>“Thật vô lễ, các người chỉ là hạ nhân mà dám bước thêm một bước nữa, hoàng đế sẽ cho ngũ mã phanh thây các ngươi, tru di cửu tộc các ngươi,” cô gái Băng Băng, tức giận và phẫn nộ, ra lệnh cho các bảo vệ mặc đồng phục ở bên trái, cô vung tay khiến các bảo vệ hoảng sợ và liên tục lùi lại.</p>',
        '061460f1-45fd-40a8-b243-5da3f0f35523',
        '2025-05-06 09:15:00.000000',
        'vi');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('f8e08934-24e1-47f3-9a22-1eb814e2fda3',
        1,
        'Cái chết của sự yêu quý',
        'ea728084-f3fe-4ea8-9d32-83653bee2580',
        '
        <p>Đêm, trời tối đen như mực.</p>
        <p>Một đám mây đen dày đặc bao phủ toàn bộ học viện Vũ An, bầu trời tối tăm và yên lặng, giống như một cơn lốc xoáy khổng lồ nuốt chửng toàn bộ học viện vào trong.</p>
        <p>Ông lão trực đêm trong phòng trực đã bật đèn lên, khoác một chiếc áo mỏng. Nhìn ra bầu trời đen kịt, ông lão dùng tay dụi mắt, rồi chiếu đèn pin nhìn lên bầu trời.</p>
        <p>“Ôi trời ơi!” Ông lão kêu lên với vẻ hoảng sợ trong mắt, như thể đã bị một điều gì đó làm sợ hãi, sau một lúc lâu mới bình tĩnh lại, lẩm bẩm: “Đêm tối gió lớn, máu che phủ trời, chắc chắn có điềm báo.”</p>
        <p>Mới chỉ là đầu tháng Mười, nhưng gió thổi lại lạnh lẽo và buốt giá, toàn bộ khuôn viên trường đột nhiên trở nên hoang vắng, giống như một thành phố cổ bị bỏ hoang. Có vài con quạ bay trên bầu trời, đậu trên chiếc đồng hồ ở tòa nhà nghệ thuật của trường, tiếng kêu vang vọng, như tiếng kêu sợ hãi, lo lắng, bất lực và sụp đổ.</p>
        <p>Những con quạ đứng ở đỉnh tòa nhà của trường, với đôi mắt kỳ quái của chúng, quan sát từng góc của khuôn viên trường, phát tán khí tức của cái chết. Nhìn thẳng vào phòng ngủ nữ sinh 411.</p>
        <p>Trong phòng, Đồng Tiểu Mai không thể ngủ được vì lạnh, cô kéo chăn ra và đứng dậy. Lúc này, các bạn gái khác trong phòng đều đã ngủ say, Đồng Tiểu Mai cố gắng hành động nhẹ nhàng, sợ làm các bạn khác tỉnh dậy.</p>
        <p>“Trời đã vào tháng mấy rồi, sao lạnh quá vậy? Không lẽ sắp có mưa?” Đồng Tiểu Mai ôm hai tay vào người, từ từ đi đến cửa kính ban công của phòng ngủ.</p>
        <p>Khi vừa kéo cửa kính, đột nhiên cô nghe thấy tiếng đàn.</p>
        <p>“Đinh——đinh——dong——dong”</p>
        <p>Nếu đoán không nhầm, đây có lẽ là âm thanh của đàn cổ cầm.</p>
        <p>Là một sinh viên nổi bật của khoa biểu diễn, dù đàn cổ cầm là môn học bắt buộc, nhưng cũng rất quen thuộc, vì mỗi năm đều có màn biểu diễn đàn cổ cầm trong buổi tối, nên Đồng Tiểu Mai không cảm thấy lạ lẫm.</p>
        <p>Nhưng giữa đêm khuya thế này, ai lại đang chơi đàn cổ cầm?</p>
        <p>Âm thanh nghe có vẻ buồn bã, như tiếng suối róc rách, lại giống như vài người phụ nữ đang thì thầm, âm thanh lan từ xa đến gần, thẳng đến tai Đồng Tiểu Mai, khiến cô cảm thấy lạnh gáy.</p>
        <p>Đồng Tiểu Mai cảm thấy đầu mình buốt lạnh, giật mình hét lên: “Ai đó?”</p>
        <p>Không có ai trả lời, xung quanh hoàn toàn yên lặng, trong ký túc xá chỉ có tiếng gió lạnh thổi vù vù. Âm thanh cũng biến mất theo.</p>
        <p>“Chuyện gì vậy, có lẽ mình nghe nhầm, có thể là do quá mệt mỏi.”</p>
        <p>Khi Đồng Tiểu Mai vừa quay lại để tiếp tục ngủ, âm thanh lại vang lên, liên tiếp và ngày càng cấp bách, giống như có một cái đàn cổ cầm đang được đặt trên ban công, và ai đó đang kéo dây đàn.</p>
        <p>Âm thanh đàn cổ cầm vang lên liên tục: “Đinh đinh dong dong đinh đinh dong dong dong dong dong dong đinh đinh đinh đinh đinh đinh dong dong”.</p>
        <p>Đồng Tiểu Mai cảm thấy toàn thân lạnh buốt đến tận xương, lạnh đến mức các dây thần kinh như bị đông cứng. Cảnh tượng trong phòng ký túc xá biến thành những sóng gợn lăn tăn, méo mó, giống như một bức tranh khổng lồ bị kéo dãn. Âm thanh đó vẫn còn, giống như nam châm hút lấy cô, nhưng cô không dám nhìn vào, cảm giác như mình đang ở trong một cơn lốc còn đáng sợ hơn cả bão tố. Có thể, nếu cô quay đi thì sẽ không còn đường trở lại. Cô nhắm mắt, lắc đầu, cố gắng thức dậy từ cơn ác mộng, mong thoát khỏi vận rủi này.</p>
        <p>Lúc này, một giọng nói đã làm tan biến âm thanh của đàn cổ cầm: “Tiểu Mai, sao lại đứng ở ban công vậy? Về phòng đi, ở đó lạnh lắm.”</p>
        <p>Đồng Tiểu Mai nghe rõ ràng đó là giọng của Hứa Tuyết trong phòng ký túc xá, cảm thấy như được cứu rỗi, liền mở mắt ra.</p>
        <p>Một hình bóng đầy máu đứng trước mặt Đồng Tiểu Mai, mặc bộ đồng phục của ký túc xá, nhưng gương mặt thì vô cùng ghê rợn, đầy những vết thối rữa, một con mắt lồi ra khỏi khuôn mặt, miệng bị méo mó và nứt nẻ, nhưng giọng nói vẫn rõ ràng: “Tiểu Mai, sao đứng ngẩn ngơ ở đó?”</p>
        <p>Đồng Tiểu Mai hét lên và quay người lại, hướng về phía ban công. Vào đúng khoảnh khắc đó, Đồng Tiểu Mai như bị ma ám.</p>
        <p>“Hoàng thượng, nô tì cầu xin người hãy tha cho nô tì.”</p>
        <p>Đồng Tiểu Mai nghiêng đầu, ánh mắt chứa đầy nước mắt, nhìn chằm chằm vào bóng tối mịt mù của ban công. Cô mỉm cười, nhìn vào bóng tối và cười.</p>
        <p>“Hoàng thượng, nô tì đã chuẩn bị sẵn sàng.”</p>
        <p>Đồng Tiểu Mai leo lên lan can đá của ban công và đứng đó.</p>
        <p>Gió nhẹ thổi qua khuôn mặt xinh đẹp của cô, dù trong đêm tối như mực, vẫn có thể thấy được vẻ đẹp của cô, một vẻ đẹp làm say đắm lòng người.</p>
        <p>Một sinh viên khoa biểu diễn với vẻ ngoài tuyệt mỹ như vậy, nếu có thêm thời gian, chắc chắn sẽ là một ngôi sao nổi bật được nhiều người ngưỡng mộ. Nhưng vẻ đẹp của cô đã kết thúc ngay trong đêm nay.</p>
        <p>Hứa Tuyết đứng trước mặt, cố gắng ngăn cản, nhưng giọng nói đó đối với Đồng Tiểu Mai như từ một thế giới khác, không thể cản trở cô, khiến cô thực hiện những hành động kỳ quái và nói những lời lạ lùng.</p>
        <p>Đồng Tiểu Mai vén làn da trắng mịn của mình, cười khúc khích.</p>
        <p>“Hoàng thượng, nô tì có đẹp không?”</p>
        <p>Đồng Tiểu Mai tháo từng cúc áo, lớp áo của cô, giống như lớp vảy rắn.</p>
        <p>“Ghê tởm” Đồng Tiểu Mai với vẻ mặt ngọt ngào, lao về phía lan can của tòa nhà.</p>
        <p>Một tiếng “rầm” vang lên, Đồng Tiểu Mai ngã xuống đất, cơ thể nát vụn, máu tươi nhuộm đỏ toàn bộ toàn bộ mặt đất xung quanh. Tuy nhiên, mặt cô vẫn như đang mỉm cười.</p>
        <p>Ba tháng sau…</p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('3f4398cd-f79d-43c6-adb0-0cd919cbf42e',
        2,
        'Vào một đêm trăng sáng...',
        'ea728084-f3fe-4ea8-9d32-83653bee2580',
        '
        <p>Hai cô gái đứng ở mép tầng cao nhất của tòa nhà Y Garden, hát và nói những lời của triều đại cổ đại, so sánh mình với những quý phi trong cung đình cổ đại, hoàn toàn không để tâm đến tình cảnh nguy hiểm của mình.</p>
        <p>Hai cô gái này chính là Băng Băng và Hứ Tuyết trong phòng ký túc xá nữ 411. Họ trang điểm đậm, mặc đồ, dưới ánh trăng trông rất quyến rũ và nổi bật. Bên cạnh họ, vài bảo vệ đang từ từ tiếp cận.</p>
        <p>“Thật vô lễ, các người chỉ là hạ nhân mà dám bước thêm một bước nữa, hoàng đế sẽ cho ngũ mã phanh thây các ngươi, tru di cửu tộc các ngươi,” cô gái Băng Băng, tức giận và phẫn nộ, ra lệnh cho các bảo vệ mặc đồng phục ở bên trái, cô vung tay khiến các bảo vệ hoảng sợ và liên tục lùi lại.</p>
        <p>“Ôi, các cô diễn xuất thật quá sâu rồi,” một bảo vệ nói.</p>
        <p>Tại tòa nhà Y Garden, hàng ngàn giảng viên và sinh viên đang lo lắng ngẩng lên nhìn.</p>
        <p>“Lính cứu hỏa đến chưa? Sao lâu vậy, mẹ kiếp, đến khi có sự cố lớn thì bọn họ chạy chậm hơn cả rùa, gọi thêm một lần nữa đi,” trưởng khoa quát, tất cả sự tức giận trút vào một giảng viên trẻ tuổi đứng bên cạnh.</p>
        <p>Giảng viên trẻ tuổi run rẩy, lấy điện thoại ra, gọi 119.</p>
        <p>“Á aaaaaaaa.”</p>
        <p>Lúc này, một cô gái hét lên từ xa, ánh mắt đầy sợ hãi như vừa nhìn thấy cảnh tượng khủng khiếp nhất trong đời.</p>
        <p>Các giảng viên và sinh viên có mặt cũng bị tiếng hét của cô gái đó làm cho hoảng sợ.</p>
        <p>“Á aaaaaaaa, thầy ơi,” cô gái nắm tay giảng viên trẻ, lắc lắc.</p>
        <p>Giảng viên trẻ vốn đã rất lo lắng, bị cú sốc bất ngờ này làm rơi điện thoại xuống đất, hoảng loạn không biết phải làm sao. Trưởng khoa đang bị sự việc khiến đầu óc choáng váng, lại thấy không biết cô gái đó đang nói gì, liền quát lên: “Gì? Không thấy tòa nhà đang xảy ra chuyện gì à? Còn chưa biết à?”</p>
        <p>“Dạ,” cô gái nói trong tiếng nấc, nước mắt tuôn trào, nhưng ánh mắt lại rất bình tĩnh, như đang hóa đá, nói trong đau khổ: “Có một cô gái trong phòng ký túc xá 411 đã treo cổ tự tử, ôi ôi.”</p>
        <p>“Cái gì?” Nghe thấy điều này, trưởng khoa kinh ngạc đến mức mắt như muốn nổ tung, lùi lại vài bước, toàn thân đều bị sợ hãi. Các giảng viên và sinh viên xung quanh cũng hoảng sợ.</p>
        <p>Khi mọi người còn đang hoang mang vì tin tức bất ngờ này, đột nhiên bảo vệ la lên: “Cô gái!”</p>
        <p>Nhưng đã quá muộn, Hứa Tuyết đã cởi đồ, nhảy từ tầng cao hàng chục mét xuống.</p>
        <p>Còn Băng Băng vì cởi đồ chậm hơn và không kịp nhảy, bị một số bảo vệ nhanh tay giữ lại, áp xuống đất.</p>
        <p>“— Đó là đồ của tôi, trả lại, trả lại đây!” Băng Băng bị giữ lại, la hét hướng về phía tòa nhà, giống như một con cáo đang bị trói.</p>
        <p>Sau khi các bác sĩ pháp y và cảnh sát điều tra tới, phát hiện Trương Đình Đình, người treo cổ trong phòng ký túc xá nữ 411, có dấu vết của móng tay và trong ký túc xá có dấu hiệu rõ ràng của một cuộc ẩu đả. Dựa trên dấu vết của các ngón tay còn lại trên sợi dây, kết luận cuối cùng là Trương Đình Đình bị hai cô gái cùng ký túc xá ác ý giết hại.</p>
        <p>Trong khi Hứa Tuyết nhảy lầu tự tử, Băng Băng cũng vì thế mà rơi vào tình trạng tâm thần hoảng loạn, và cái chết của họ đã trở thành một bí ẩn không có lời giải đáp, lâu dần, trở thành một hiện tượng huyền bí của học viện nghệ thuật Y Garden.</p>
        <p>Vì lúc đó rất nhiều người đã chứng kiến cảnh Hứa Tuyết nhảy lầu, và hình ảnh Đồng Tiểu Mai ngã từ lan can xuống, tin tức đã lan truyền rộng rãi trên mạng xã hội. Do đó, nhiều học sinh tin rằng trong phòng nữ 411 có ác quỷ, sẽ ám vào từng nữ sinh, khiến họ khiến họ tự sát và sát hại lẫn nhau………</p>
        <p>***************</p>
        <p>Một phòng ngủ nữ sinh đầy rùng rợn và bí ẩn, cùng với một bản nhạc hồn lúc nửa đêm không ai có thể thoát khỏi. Tại trường nghệ thuật Vũ An, có một phòng ngủ nữ sinh bị phong tỏa, nơi trước đây đã từng có bốn cô gái ở. Một người trở nên điên loạn, hai người nhảy lầu tự sát, và một người bị chính bạn cùng phòng treo cổ chết trong ký túc xá.</p>
        <p>Tại sao những cô gái tự sát lại đều đứng trên tòa nhà cao tầng, cười nói những lời lẽ cổ trang… “Hoàng thượng, thần thiếp đã đến đây”… Tại sao người bị treo cổ lại chết với nụ cười trên môi… Điểm chung của họ sau khi chết là đều mỉm cười… Liệu đó có thực sự là tự sát, bị giết hại, hay có sự tồn tại của ma quỷ, linh hồn tà ác?</p>
        <p>Bốn năm sau, căn phòng từng bị phong tỏa ấy được mở cửa trở lại. Vào đêm đầu tiên tân sinh viên Phan Mẫn dọn vào phòng, cô đã gặp phải vô số sự việc kỳ quái và đáng sợ. Sau đó, vòng xoay định mệnh sẽ mở ra cho cô, và những ngày tiếp theo, cô sẽ trải qua nhiều đêm trăng kinh hoàng cùng bạn cùng phòng của mình…</p>
        ',
        '2025-05-01 10:17:00.000000'),

        ('743c7ea9-7be0-406c-8dcf-35dbeb1fd5a0',
        3,
        'Căn phòng chết chóc 1',
        'ea728084-f3fe-4ea8-9d32-83653bee2580',
        '
        <p>“Ông ơi, ông ơi, mỗi đêm cháu đều nghe thấy tiếng bước chân đi qua đi lại trong nhà, vì tò mò nên cháu nhìn qua khe cửa.”</p>
        <p>“Cháu có thấy ai không?”</p>
        <p>“Một mảng tối đen, cháu chẳng thấy gì cả.”</p>
        <p>“Tiểu Mẫn, có những thứ không thể dùng mắt để nhìn, mà phải dùng tâm hồn. Đến khi cháu tìm thấy nó, hãy đi theo nó.”</p>
        <p>“Tiểu Mẫn sợ, Tiểu Mẫn không muốn.”</p>
        <p>“Haha, ngoan nào, Tiểu Mẫn.”</p>
        <p>Đây là lần đối thoại mà Phan Mẫn Mẫn nhớ nhất với ông của mình, và cũng là lần cuối cùng.</p>
        <p>Sau cuộc trò chuyện đó, ông đã qua đời vào ngày hôm sau, không một lời từ biệt, khiến cuộc sống của Phan Mẫn Mẫn từ nhỏ đã bị bao phủ bởi bóng tối suốt một thời gian dài.</p>
        <p>Đối với cô, ông là người thầy đầu tiên, nhiều điều cô học được từ ông đều ẩn chứa những ý nghĩa sâu xa. Mỗi lần hồi tưởng, cô luôn có thêm những nhận thức mới. Và cũng từ khi ông qua đời không lâu, gia cảnh của gia đình cô bắt đầu sa sút. Trước tiên là công ty phá sản, sau đó là vụ kiện mà mẹ cô cố gắng đòi lại công bằng cho cha cô cũng không thành công.</p>
        <p>Khi khoản nợ ngày càng đè nặng lên gia đình, thì cha cô đột ngột qua đời không rõ lý do, nhưng gia đình lại bất ngờ nhận được một khoản tiền bảo hiểm lớn từ công ty bảo hiểm, có lẽ đó là điều cuối cùng mà cha để lại cho mẹ con họ. Kể từ đó, gia đình vốn dĩ hạnh phúc của cô dần tan vỡ, ngay cả bạn bè thân thiết và người thân cũng xa lánh hai mẹ con cô.</p>
        <p>Phan Mẫn yêu thích vẽ, vì cô muốn giữ lại những ký ức đẹp đẽ trước kia, nên cô đã đăng ký vào một trường nghệ thuật, chuyên ngành mỹ thuật. Còn mẹ cô, sau biến cố đó, không làm luật sư nữa, mà chuyển sang mở một quán cà phê và một cửa hàng nhỏ, dần dần cuộc sống cũng ổn định trở lại.</p>
        <p>Trưa hôm nay, Phan Mẫn đã ngồi xe suốt vài giờ để đến ngôi trường mà cô đã mơ ước từ lâu. Hôm nay là ngày cuối cùng để nhập học, mặc dù cô đến hơi muộn, nhưng đó là thời điểm hoàn hảo với cô, vì cô không thích những đám đông chen chúc. Sau khi hỏi bảo vệ vị trí văn phòng giáo viên, Phan Mẫn nhìn lên trời, không dám chậm trễ thêm, sợ rằng lớp học đã bắt đầu, nên cô nhanh chóng kéo vali đi đến văn phòng.</p>
        <p>Văn phòng khoa mỹ thuật nằm trên tầng hai của tòa nhà thông tin, vì ở tầng một có phòng bảo quản, Phan Mẫn đã để hành lý của mình ở đó và nhanh chóng chạy lên tầng hai.</p>
        <p>Vừa đến tầng hai, cô thấy một nhóm nữ sinh đang tụ tập trước một văn phòng, có người che miệng cười, có người kiễng chân ngó vào trong, và một vài nữ sinh thì nắm chặt tay, trông vô cùng đáng yêu.</p>
        <p>Đã xế chiều rồi, tại sao các nữ sinh này không đi ăn mà lại kéo đến đây? Chẳng lẽ trong văn phòng này có gì hấp dẫn hơn cả nhà ăn?</p>
        <p>Phan Mẫn tiến lại gần, vỗ vai một nữ sinh đang ngẩn ngơ, hỏi: “Bạn ơi, cho mình hỏi, thầy giáo mỹ thuật có ở trong văn phòng này không?”</p>
        <p>“Cái gì, thầy giáo mỹ thuật à!”</p>
        <p>Nghe đến từ “thầy giáo mỹ thuật”, đôi mắt cô nữ sinh ngay lập tức sáng rực, hai mắt mở to, trông rất đẹp, nhưng hành động tiếp theo khiến Phan Mẫn không khỏi bất ngờ.</p>
        <p>Cô nữ sinh nắm lấy tay Phan Mẫn, má hơi ửng hồng: “Bạn là sinh viên khoa mỹ thuật à? Bạn tìm thầy Phương Tử Hạo à?”</p>
        <p>“Gì cơ? Thầy Phương!”</p>
        <p>Nghe đến tên này, các nữ sinh khác cũng như bị thôi miên, họ hưng phấn vây quanh Phan Mẫn.</p>
        <p>“Cậu là tân sinh viên khoa mỹ thuật à?”</p>
        <p>“Cậu tìm thầy Phương để đăng ký học đúng không?”</p>
        <p>“Wow~ Thật ghen tị, cậu có thể được thầy Tử Hạo hướng dẫn!”</p>
        <p>“Tớ cũng muốn chuyển sang khoa mỹ thuật quá, huhu, biết sớm có thầy Phương đẹp trai như thế này thì tớ đã không đăng ký khoa diễn viên rồi.”</p>
        <p>Phan Mẫn ngạc nhiên: thầy Phương Tử Hạo lại được các sinh viên ngưỡng mộ đến vậy sao? Những cô gái này không phải sinh viên khoa mỹ thuật, mà đến từ các khoa khác. Không lạ khi cô hỏi bảo vệ về văn phòng giáo viên khoa mỹ thuật, người bảo vệ thậm chí có thể đọc thuộc lòng vị trí văn phòng, rõ ràng là thầy giáo mà cô sắp gặp có sức ảnh hưởng đặc biệt trong trường.</p>
        <p>Phan Mẫn cũng trở nên tò mò.</p>
        <p>“Bạn là tân sinh viên, vậy bạn có thể vào văn phòng rồi,” một nữ sinh hào hứng nói.</p>
        <p>Khi Phan Mẫn đang bối rối, phía trước đột nhiên mở ra một lối đi, và cô cảm thấy có hàng chục bàn tay nhẹ nhàng đẩy lưng cô vào văn phòng. Cuối cùng, cô bị đẩy đến trước mặt một người đàn ông đang cúi đầu xem tài liệu.</p>
        <p>Trong văn phòng còn có năm giáo viên khác cùng khoa. Khi thấy nhóm đông đúc bước vào, dù là nam hay nữ giáo viên đều không giấu được sự ghen tị. Các nam giáo viên ghen tị với Phương Tử Hạo, còn các nữ giáo viên thì đố kị với những nữ sinh xinh đẹp đang can đảm tiếp cận thầy.</p>
        <p>Phương Tử Hạo đang kiểm tra thông tin của tân sinh viên, anh nhận ra sự hiện diện của nhóm nữ sinh, bất lực lắc đầu, vốn định khiển trách một lần, nhưng khi ngẩng đầu lên, anh bất ngờ đứng sững, cây bút trong tay cũng vô thức rơi xuống bàn.</p>
        <p>Phan Mẫn nhìn thấy khuôn mặt của Phương Tử Hạo lần đầu tiên, cũng không khỏi ngạc nhiên. Ánh mắt hai người chạm nhau, cả hai im lặng không nói gì một lúc lâu.</p>
        <p>Cả hai như đã từng gặp nhau, nhưng lại không rõ tại sao cả hai lại có cảm giác quen thuộc như vậy. Là đã gặp trong mơ, hay đó là duyên định sẵn từ kiếp trước?</p>
        <p>Phan Mẫn từ nhỏ đã có khả năng nhận diện tốt, thậm chí trong suốt thời gian trung học, cô có thể vẽ chính xác khuôn mặt người mà cô đã từng gặp. Vậy mà với người thầy trẻ đẹp trai trước mặt này, cô dám khẳng định rằng mình chưa từng gặp qua, nhưng tại sao lại có cảm giác như đã gặp từ lâu, hơn nữa lại rất quen thuộc.</p>
        <p>Anh ta cuộc là ai?</p>
        <p>Thấy hai người cứ nhìn nhau mà không nói gì, một nữ sinh bên cạnh sốt ruột lên tiếng: “Thầy Phương, hai người quen nhau à?”</p>
        <p>“Quen nhau?” Những nữ sinh khác nghe thấy câu này, lập tức nét mặt thay đổi, trông như đang coi Phan Mẫn là kẻ địch.</p>
        <p>“Đây…” Phan Mẫn bị đánh thức khỏi dòng suy nghĩ, nhận ra có hàng chục ánh mắt đang nhìn chằm chằm vào mình, làm cô nổi da gà, vội vàng giải thích.</p>
        <p>Bị nhóm nữ sinh này coi là kẻ địch thật không tốt chút nào, nếu nghiêm trọng, có lẽ cô sẽ không thể tiếp tục học ở trường này nữa, nhất là trong ngôi trường nghệ thuật danh tiếng này, bị nhóm sinh viên khoa diễn xuất nhắm tới.</p>
        <p>“Em đến rồi.”</p>
        <p>Phương Tử Hạo nhìn Phan Mẫn, khuôn mặt ban đầu vô cảm của anh đột nhiên trở nên dịu dàng, điều này không qua được ánh mắt của đám nữ sinh đứng sau Phan Mẫn.</p>
        <p>“Em đến… em đến để đăng ký,” Phan Mẫn cảm thấy lạnh sống lưng, như thể bất cứ lúc nào cũng có một cơn bão lớn quét qua, vội vàng giải thích: “Lần đầu gặp mặt, thầy Phương, em là tân sinh viên khoa mỹ thuật, em tên là Phan Mẫn, hôm nay em đến để đăng ký, hơi muộn một chút, em xin lỗi.”</p>
        <p>Trong lúc bối rối, Phan Mẫn đã nghĩ ra cách giải thích hợp lý, thoát khỏi nghi ngờ rằng cô và thầy Phương đã quen biết từ trước, đồng thời khiến nhóm nữ sinh xung quanh bớt cảnh giác với cô. Cô tưởng rằng mọi chuyện đã qua, nhưng không ngờ những lời tiếp theo của Phương Tử Hạo lại khiến cô cảm thấy như mọi thứ sắp sụp đổ.</p>
