VALUES ('9e530ef0-fc69-4f1a-a12b-803c687c006e',
        true,
        'Quỷ Sự Miền Quê Xưa',
        '<p>Xóm tui một nơi hẻo lánh hẻo của miền tây, những năm cuối 1800 đầu 1900, thời mà chưa biết đến điện là gì, nhà thì cả một vùng rộng lớn được vài ba cái nóc. Cây cối mọc um tùm như rừng như hang, mặt đất quanh năm chẳng được 1 tia nắng chiếu xuống, trên bờ thì nào tre nào keo, cặp sông thì dừa nước, bần, ô rô, cám dây chằng chịt. Mồ hoang mã lạng chẳng biết đâu mà lần, cái thời mà còn hùm beo thú dữ đi nghênh ngang khắp chốn. Người ta có câu “dưới sông sấu bắt, trên bờ cọp tha” cũng từ những vùng quê này mà ra. Xóm tui tuy đất rộng nhưng người lại thưa, nhà lại cách nhau đến vài mẫu đất, mỗi khi có đám tiệc gì cũng chạy rã cặp dò mới mời được hết xóm.</p>',
        '061460f1-45fd-40a8-b243-5da3f0f35523',
        '2025-05-06 09:15:00.000000',
        'vi');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('9e4f7a4a-e2b4-449a-8dc7-70db963a6efd',
        1,
        'Chương 1',
        '9e530ef0-fc69-4f1a-a12b-803c687c006e',
        '
        <p>  Xóm tui một nơi hẻo lánh hẻo của miền tây, những năm cuối 1800 đầu 1900, thời mà chưa biết đến điện là gì, nhà thì cả một vùng rộng lớn được vài ba cái nóc. Cây cối mọc um tùm như rừng như hang, mặt đất quanh năm chẳng được 1 tia nắng chiếu xuống, trên bờ thì nào tre nào keo, cặp sông thì dừa nước, bần, ô rô, cám dây chằng chịt. Mồ hoang mã lạng chẳng biết đâu mà lần, cái thời mà còn hùm beo thú dữ đi nghênh ngang khắp chốn. Người ta có câu “dưới sông sấu bắt, trên bờ cọp tha” cũng từ những vùng quê này mà ra. Xóm tui tuy đất rộng nhưng người lại thưa, nhà lại cách nhau đến vài mẫu đất, mỗi khi có đám tiệc gì cũng chạy rã cặp dò mới mời được hết xóm. Bao nhiêu đó chắc mọi người cũng mường tượng được khung cảnh quê tui như thế nào. Và câu chuyện mà tui muốn kể với mọi người bắt đầu từ sự hoang sơ của xóm mình, vì hoang sơ đến vậy nên những chuyện yêu ma quỷ quái là rất bình thường. Câu chuyện được nội tui kể lại, và tui muốn vào vai nội để kể mọi người nghe sát câu chuyện hơn. Chuyện là gần xóm tui có một ngôi mộ của gia đình người địa chủ, gia đình ông địa chủ đó là người hoa nên rất chú trọng về phần âm trạch và cũng vì một phần thời đó đạo tặc, trộm mộ hoành hành nên gia đình người chủ đó trấn yểm rất kỹ. Sau này vì chiến tranh nên chẳng ai biết người địa chủ đó đi đâu bỏ lại khu mộ hoang tàn, lao sậy cao quá đầu, dứa gai mọc um tùm không người chăm sóc. Trong mộ đó có rất nhiều rắn độc, nào lục, mái gầm, hổ chúa nằm vắt vẻo trên sàn nhà mồ. Vì hoang quá hoang vắng, điêu tàn nên chuyện ma quỷ bắt đầu từ đây. Một hôm kia có một người trong xóm đi chăn trâu gần đó, vì khu đó cỏ nhiều mà lại có chỗ trủng cá nhiều vô kể, vì ông ấy mãi mê bắt cá mà quên mất trời chiều tắt nắng hồi nào không hay đến khi sực nhớ ra thì chẳng thấy trâu đâu, ông đó tìm một hồi mà không thấy thầm nghĩ chắc là trâu no nên về chuồng. Ông liền xách mấy xâu cá thong thả đi về, đến khi về đến nhà thì chẳng thấy con nào ở chuồng, vậy là hai vợ chồng đốt đuốc đi tìm. Tìm mãi đến nữa đêm mà không thấy, ông nói vợ:<br>
            Có khi nào nó đi lạc vô đất mộ hay không!<br>
        Bà vợ cũng gật đầu nói: chắc là nó mãi mê ăn nên lạc vô trông đó, mà giờ tui với ông làm sao vô đó được? Trông đó toàn là rắn rết còn…. bà vợ bỏ lửng câu nói.<br>
            Ông chồng ngẫm nghĩ hồi lâu rồi nói: hay là mình về nhờ vợ chồng a hai với bác ba vô tìm phụ, bác ba ổng giỏi về mấy chuyện kia….lắm.<br>
            Vậy là hai vợ chồng đi về nhờ vợ chồng người a hai cùng ông bác đốt đuốc quay lại, vừa mới bước chân vô trong khu mộ ông ba chợt sững nguoi vì ông thấy xa xa trong đó có một cái bóng người đang ngồi xỏm mà cầm cái gì đó đưa vô miệng, do quá xa mà ánh đuốt lại nhá nhem nên ông không thấy rõ. Ông nói với người a Hai kế bên: thằng Hai nảy giờ mầy có thấy gì không?<br>
        Ông a Hai lắc đầu: con có thấy gì đâu!<br>
        Bác ba thấy vậy liền đi tới thêm mấy bước thì một mùi tanh nồng sộc thẳng vào mũi, trong cái mùi ấy có mùi tanh của máu lẫn nước tiểu cùng phân trâu hoà quyện. Ông liền đi nhanh tới, đến khi mọi người tới nơi thì một cảnh hãi hùng đập vào mắt. Đó là xác hai con trâu nằm chết, xung quanh nội tạng mằm vươn vãi khắp nơi, máu thì lênh láng. Do vợ chồng ông chủ trâu và ông a Hai không thấy cái cảnh mà ông bác Ba thấy nên cứ nghĩ là hùm beo gì đó về đây bắt trâu ăn thịt, hai vợ chồng liền quỵ xuống. Cả gia tài chỉ cơ mỗi hai con trâu mà giờ lại bị như vậy. Ông a Hai thì lại nghi ngờ, quay qua nói với Bác Ba:<br>
            Trước giờ xứ mình đâu nghe hùm beo về xóm bắt trâu bò ăn thịt đâu Bác ba?<br>
            Ông bác ngẫm nghĩ liền nói:<br>
        Bây giờ đêm đã khuya, mình cũng không thể khiên xác hai con trâu này về nhà được, giờ cứ về nhà trước. Sáng mình đi nhờ thêm chòm xóm ra khiên nó về, ở đây rắn rết nhiều không nên ở lâu.<br>
            Ông chủ trâu nói : nhưng mà để đây đến sáng tụi hùm beo kia ăn hết thì sao bác ba?<br>
        Ông bác lại nói: nó mới ăn xong còn no, nó không ăn liền được đâu.<br>
        Vậy là mọi người đi lục tục kéo nhau đi về, trước khi đi ra khỏi khu mộ ông Bác Ba len lén nhìn lại thì thấy sâu trong khu mộ có một đôi mắt đỏ như hai cục than nhìn chằm chầm về phía mọi người……<br>
        Còn tiếp…..</p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('8c23aa3f-4820-4cda-8273-f0f8705ba82c',
        2,
        'Chương 2',
        '9e530ef0-fc69-4f1a-a12b-803c687c006e',
        '
        <p>  Chap 2:<br>
        Đêm hôm ấy về Bác ba trằn trọc mãi không thể nào ngủ được, ông lại nhớ về những ngày xóm mình mới đến đây khai khẩn đất hoang, từ loe hoe một hai nóc nhà đến giờ đã thành xóm thành làng. Thuở ấy tuy nơi đây hoang sơ, rừng thiêng nước độc nhưng bù lại đất đai màu mỡ, cá tôm, thú rừng nhiều vô kể.  Trong nhóm những người đầu tiên đến đây khai hoang có ông Trương Thuận, ống vốn xuất thân giang hồ, là người của Thiên Địa Hội vì tránh sự truy bắt của quan quân triều Thanh nên lưu lạc đến đây cùng mọi người nơi đây khai khẩn đất hoang. Ông có rất nhiều tài lạ như phong thủy, bói toán, võ nghệ, bốc thuốc cứu người. Vì vậy trong xóm ông rất được kính trọng và yêu mến. Khi đến đây ông cũng có chút của cải mang theo cộng thêm nơi đây có rất nhiều thú rừng cũng như sản vật vì vậy mà chẳng mấy chốc gia đình đã yên ổn và khá giả nhất trong xóm. Từ đó ông bắt đầu thuê thêm người vừa khai khẩn thêm đất vừa khai thác sản vật bên đây đưa về trung quốc để bán. Thuở đầu ông đối với mọi người xung quanh rất tốt, nào là giúp người coi đất dựng nhà rồi hái thuốc chữa bệnh, nhưng không ai ngờ tới đó chỉ là cái lớp vỏ bọc để ông thực hiện âm mưu đen tối của mình. Khi ông đặt chân yên ổn ở đây và làm ăn khá giả, ông đã trở về trung quốc mang hài cốt song thân qua đây để mang táng với lý do tiện bề hương khói. Ông thuê người xây dựng một khu mộ rất to, ngta ước tính cũng phải gần chục mẫu đất, xung quanh ông trồng rất nhiều cây cối có gai như tre, dứa gai hoang, ô rô, keo, xương rồng.. để làm rào, bên trong lại cho xây dựng rất nhiều hầm mộ, nhà ở canh mộ… Ông phải xây dựng mất gần ba năm mới hoàng thành khu mộ ấy. Và cũng từ đây ác mộng mới bắt đầu đến với dân trong xóm, một ngày cuối tháng 6 trời mưa đêm rỉ rả, thằng Đen con bà 2 Dần cùng đứa e nó rủ nhau đốt đuốc đi bắt ếch  về mai kho cho cha mẹ dở cơm ra đồng. Hai ae bắt đến giữa đêm thì được cũng kha khá nên thằng Chuột em thằng Đen mới nói với anh nó:<br>
                Bắt nhiêu đây chắc cũng đủ rồi a hai ơi, mình về đi, e buồn ngủ với lạnh quá.<br>
        Thằng Đen thấy thương em nên nói: Ừ thôi hai anh em mình quay lại bắt dài dài về nhà chắc cũng được thêm 1 ít. Gọng lại cho chiều mai tía làm về có mồi lai rai.<br>
            Thật thương làm sao, người con hiếu<br>
        Số đoản mệnh, người đầu bạc tiễn kẻ tóc xanh<br>
            Trong đêm mưa gió não nề,<br>
        Con ra đi mãi, tìm hoài chẳng ra…<br>
        Ngã ba tìm được cái đầu,<br>
        Còn thân xác ấy, nơi nào hỡi con…<br>
        Hai anh em mới quay lại đến đoạn đầu xóm thì thằng Đen nghe tiếng ếch kêu râm rang ở trong vườn hoang cạnh đó, nó mới đem mấy xâu ếch cho thằng Chuột rồi kêu em về trước. Còn nó thì đi thẳng vô trong vườn, lúc đầu nó bắt được khá nhiều nên thầm nghĩ chắc nơi đây ít ai bắt nên còn nhiều. Nhưng bắt được một lúc thì nó chợt nhớ ra ếch tháng này thì làm sao mà có kêu hay tục như hồi mới rớt hột mưa chứ, mà còn có ếch cặp nữa. Nó bắt đầu có cảm giác rờn rợn, định quay đầu về thì có tiếng cười sằng sặc ở phía trước. Lúc thì cười như mấy đứa trẻ con, lúc thì như tiếng người già. Thằng Đen lúc này nó mới biết là hiện tại nó đã gặp gì rồi, nó quay đầu chạy, mà chạy càng nhanh thì tiếng cười kia lớn. Vừa ra gần tới đầu sớm thì nó thấy một cái bóng người đứng cạnh bụi tre, mà lạ cái hai tay người này rất dài, nó không kịp nghĩ nhiều liền la lên với người kia: cứu con với, trong kia có ma. Chắc là nó nghĩ người trong xóm cũng đi bắt ếch như nó, nhưng mà nó đã sai. Nó vừa chạy đến thì … Thiệt khủng khiếp, mặt người kia là một màu xanh, mắt thì đỏ rực, răng nanh dài ra khỏi miệng, móng thì như chim đại bàng. Lại một tiếng cười sằng sặc, không đợi nó phản ứng tay người kia…(phải gọi là bóng ma kia mới đúng) đã chọp thẳng vào cổ nó, một tiếng răn rắc, kèn kẹt khô khốc giữa đêm khuya. Bóng ma kia đã vặn đứt đầu của thằng Đen rồi vứt qua một bên, sau đó nó mang theo cái xác không đầu đi ngược trở vào trong khu vườn hoang vắng kia. Trở lại với thằng Chuột sau khi về đến nhà, nó mang mấy xâu ếch đi gọng rồi tắm rửa, nó mắt nhắm mắt mở bay tọt vô mùng đánh một giấc ngon lành mà đâu hay người anh yêu quý của nó đã bỏ mạng dưới tay cái bóng ma quỷ kia…<br>
        Sáng ra hai vợ chồng bà 2 cũng không hay mọi chuyện cứ nghĩ là hai đứa con đi bắt ếch đêm nên giờ còn ngủ trong mùng, cứ vậy mà bà cùng chồng lục đục làm ếch nấu cơm để đi ra đồng. Mới ra tới đầu xóm thì bà đã nghe tiếng người la hét thất thanh, sau đó là có mấy người làm đồng gần đó chạy lại. Thấy có sợ chẳng lành nên vợ chồng bà cũng nhanh chân đến xem, vừa đến nơi đập vào mắt hai vợ chồng là một cái đầu người nằm cạnh bụi tre, máu me bê bết. Vì cái đầu nằm úp mặt xuống đất nên không ai biết nạn nhân là ai, vì sao mà gặp cảnh nguy bỏ mạng như vậy. Bác Ba lúc ấy còn là thanh niên, gia đình có truyền thống võ nghệ lâu đời thuở nhỏ ông theo gia đình vào nam ra bắc vì thời cuộc mà lưu lạc về đây nên tính ông rất gan dạ. Ông tiến lên dùng cành cây để đở cái đầu xoay lại, lúc này vợ chồng bà 2 Dần và mọi người mới thấy rõ mặt nạn nhân. Lúc đầu hai người còn chẳng tin vào mắt mình vì lúc sáng ông bà đi Ae thằng Đen còn ngủ trong mùng mà sao giờ thằng Đen lại chết ở đây! Hai người như chết đứng tại chỗ, có mấy người tin ý khi nhận ra là thằng Đen thì quay qua đở hờ hai người sợ vì sốc mà té xỉu. Bà 2 khi nhận ra đó là con mình thì chỉ kịp kêu lên 1 tiếng: “Đen”, rồi ngất xỉu luôn tại chỗ, ông hai tuy là đàn ông nhưng cũng chẳn khá hơn là mấy. Ông khụy xuống đó rồi ngồi thất thần giống như cái xác không hồn…….<br>
        </p>
        ',
        '2025-05-01 10:17:00.000000'),

        ('4bdaaf87-dba8-4f7d-9ad0-6451a63a0878',
        3,
        'Chương 3',
        '9e530ef0-fc69-4f1a-a12b-803c687c006e',
        '
        <p>Quỷ Sự Miền Quê xưa<br>
            Chap 3<br>
        Thằng chuột nó còn đang ngủ ngon thì bị tiếng ồn ào bên ngoài đánh thức, nó thò đầu ra khỏi mùng dõng tai lên nghe coi có chuyện gì mà hôm nay mọi người không ra đồng mà lại tụ tập nó chuyện rơm rã vậy. Trong cái suy nghĩ non nớt của nó chợt loé lên: hay là trong xóm bắt được còn gì đó đi lạc vào xóm? Nó suy nghĩ như vậy cũng không có gì là lạ khi cái xóm này nằm lọt thỏm giữa khu rừng nguyên sơ.   Lúc thì bầy heo rừng, lúc thì Kỳ Đà, cá Sấu, Trăn Rắn…<br>
        Nó nghĩ vậy nên tung người cái vèo ra khỏi giường, không kịp rửa mặt, nó chạy thẳng về hướng mọi người đang nói chuyện. Ra đến nơi thú rừng đâu không thấy? Chỉ thấy tía má nó được mọi người dìu đi, tóc tai rủ rượi. Nó ngơ ngác đứng nhìn mà không biết tía má nó đang bị làm sao? Một thằng nhỏ trong xóm chạy lại nói với nó:<br>
            Anh hai mầy bị con gì ăn thịt chết rồi, tao nghe người trong xóm nói chỉ còn có cái đầu nằm ở đầu xóm.<br>
        Nó chết sững tại chỗ, tai nó nghe ong ong như ngàn tiếng sét đánh xuống cùng lúc.<br>
        Quay lại hiện trường, nơi mà thằng Đen đã bỏ mạng, còn mấy người trong xóm cùng bác Ba đang ở đó tìm xem phần thân thể nó nằm ở đâu? Mấy người bàn tán xôn xao, người thì nói nó bị hổ vồ, người thì lại nói nó bị cá sấu lên bờ cắn chết. Lần theo vết máu đi sâu vào trong một đoạn thì không thấy gì nữa, mấy người tìm đến giữa trưa thì thấm mệt, một người trong xóm nói:<br>
        Hay là mình về nghĩ ngơi ăn chút gì dằn bụng đi rồi quay lại tìm tiếp, chứ sáng giờ mọi người cũng mệt rồi, có khi thật là nó bị sấu lên bờ bắt thiệt rồi.<br>
        Bác ba quay sang nhìn ông Năm trưởng xóm, ông năm trầm ngâm một lúc rồi gật đầu nói với mọi người:<br>
        Mọi người về ăn miếng gì cho đỡ đói rồi tập trung ra đây tìm tiếp, thằng ba mầy ghé qua nhà bác ăn luôn cho gần khỏi chạy về nhà bây cho xa.<br>
        Vậy là mọi người lục tục ra về, bác ba thì ghé qua nhà ông năm.<br>
        Trong lúc ăn cơm bác ba thấy ông năm trầm ngâm thì hỏi:<br>
        Bác năm thấy cái chết của thằng đen có gì lạ không?<br>
        Ông năm bỏ đũa quay qua nhìn bác ba rồi nói:<br>
        Tao thấy thằng đen không giống như bị hổ vồ hay bị thú rừng ăn thịt, nếu là bị hổ vồ hay sấu bắt chắc phải có dấu chân để lại hay ít nhất cũng còn sót lại vài mãnh thịt. Còn đằng này tìm cả buổi sáng mà chẳng thấy một dâu chân nào hay mảnh xương vụn. Chuyện này có gì đó hơi khác lạ, bây thấy sao?<br>
        Ông Năm hỏi lại bác ba.<br>
        Bác ba cũng gật đầu vừa suy nghĩ vừa trả lời:<br>
        Con cũng nghĩ vậy, mà bác có phát hiện là xung quanh chỗ thằng đen chết có cái mùi rất lạ không? Kiểu vừa tanh mà … Con cũng không biết phải diễn tả làm sao nhưng nó rất lạ không giống những mùi mà mình thường hay ngửi thấy.<br>
        Hai người cứ ngồi đó suy nghĩ mà bỏ luôn bữa cơm. Khoảng một tiếng sau thì mọi người lại tập trung tìm kiếm nhưng kỳ lạ là tìm cả một ngày trời mà không thấy bất cứ một cái gì khác ngoài vết máu kéo dài vô cái vườn hoang kia. Vậy là mọi người đành bất lực quay về nhà bà 2 Dần. Vì chỉ có phần đầu nên mọi người đành tạc một phần thân bằng gỗ để chôn cùng.<br>
        Qua cái đám tang của thằng Đen không lâu thì dân xóm lại có thêm một người chết nữa. Người này chết cũng giống như thằng Đen chỉ còn mỗi cái đầu còn phần thân thì tìm không thấy đâu, dân trong xóm bắt đầu hoang mang, đồn đoán đủ thứ chuyện. Ban đêm không ai dám ra khỏi nhà, cửa đóng then cài. Vậy mà cách mấy hôm sau lại có người thứ ba lại mất mạng y như vậy, mọi người lúc này mới tập trung với nhau cắt cử người trong xóm ban đêm đi lùng bắt xem là con gì đã vào xóm bắt người hay là ma quỷ quấy phá. Mà lạ thay từ hôm có người đi canh gác xóm làng lại yên tĩnh, không có ai bỏ mạng nữa. Nhưng khi nhóm người vừa nghĩ được hai hôm thì cảnh củ lại tiếp diễn, mà lần này không còn một người mà là hai người!<br>
        Nạn nhân là hai vợ chồng mới cưới chưa được bao lâu, chết trong chính căn nhà của họ. Hai cái đầu nằm lăn lóc trên nền nhà, máu me văng tung toé trên vách. Xung quanh cũng không tìm thấy được dấu chân con thú nào khả nghi. Lúc này mọi người mới chắc chắn rằng đây là ma quỷ gây nên. Sự việc làm mọi người sợ hãi đến nỗi ban ngày cũng không dám ra khỏi nhà, thậm chí mấy nhà ít người còn gom lại ở chung với nhau để đề phòng con ma con quỷ kia đến bắt người.<br>
        Sợ hãi như vậy cũng không phải là cách, ở trong nhà mấy hôm, có mấy thanh niên bạo gan đã chịu không được nên quyết tâm cầm theo vũ khí, gậy gộc, máu chó ra ngoài. Vừa là đi tìm con quỷ kia, vừa là tìm ít thức ăn cho người trong nhà. Trong đó có thằng Lâm, nó cũng là một đứa lì lợm, sức vóc hơn người, từng tay không vậy lộn với con heo rừng nặng gần hai tạ. Nó đi riêng mình nó, một tay cầm cây phản sáng bóng một tay cầm theo cây ba chỉa đâm ếch, luồn lách vòng quanh xóm, đi đến hơn nữa đêm mà không thấy gì? Thấy trời cũng gần sáng nên định quay về nhà ngủ, mới đi được chục bước chân thì nó nghe tiếng sột soạt phát ra từ hàng cây bên cạnh…..<br>
        </p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('4c7d2f4f-3921-4bc0-8971-4ba68edf29e0',
        4,
        'Chương 4',
        '9e530ef0-fc69-4f1a-a12b-803c687c006e',
        '
        <p>Chap 4:<br>
        Nghe tiếng sột xoạt thằng Lâm nghĩ thầm: có khi nào là heo rừng hay không? Lâu rồi không thấy con nào vô xóm, bắt được con này về mai mần thịt chia cho cả xóm cùng ăn. Nó đi chầm chậm về phía bụi cây, tay thủ chắc cây phản sáng bóng, một khi con vật kia chạy ra là nó chém ngay. Nhưng khi đến gần thì một mùi tanh tưởi đến phát ói xộc vô mũi, một cặp mắt đỏ như lửa than nhìn chầm chập về phía nó. Thằng Lâm chợt khựng lại kêu lên thành tiếng: ** nó là cọp hả? Nó liền quay đầu định bỏ chạy, nhưng làm sao một con người bằng xương bằng thịt lại có thể nhanh hơn loài yêu ma quỷ quái! Một cái bóng đen mang theo cái mùi tanh tưởi cùng bộ móng sắc như vuốt cọp chụp thẳng vào sau gáy thằng Lâm, một tiếng hét vang động vang cả xóm làng. Cũng may là thằng Lâm đoán được nếu mình quay lưng bỏ chạy nó sẽ vồ theo để chụp mình, nghĩ vậy nên khi quay lại nó đã thủ sẵn cây phản, con vật kia vừa chụp tới thì nó lật người chém một phát hết lực vào con vật kia. Ma quỷ rất kiêng kỵ những vật sắc nhọn nên dù không chém chết thì cũng làm nó không dám tấn công liều lĩnh. Một nhát chém của thằng Lâm nếu là heo rừng hay cọp mới trưởng thành chắc đã bị nó xã làm hai nữa, nhưng cái bóng đen kia chỉ thét lên một tiếng ghê rợn rồi lùi lại thủ bộ, trước ngực toát ra một luồn khói đen. Lúc này nó mới kịp nhìn kỹ con vật kia vậy mà không phải cọp hay heo rừng mà là một con vật giống như vượn, tay chân dài lêu nghêu, móng sắc, răng nhọn, nhưng lại có nét giống người.<br>
        Ở đầu bên kia của xóm, bác Ba cùng với mấy anh thanh niên đang đi thì nghe tiếng hét vang động kia lập tức chạy qua hướng này, ông Năm cùng người dân trong xóm cũng đốt đuốc chạy ra. Quay lại với thằng Lâm, lúc này nó thật sự hoảng sợ khi nhận ra một sự thật, những người bỏ mạng trong xóm chắc chắn là cái con dị hợm kia gây nên. Nó liên tiếp lùi lại, chộp lấy cây chỉa, phóng một phát về phía con quỷ quái kia rồi bỏ chạy nhưng chưa kịp chạy được mấy bước thì thấy ngực mình đau nhói, một cánh tay đã xuyên ngực nó từ lúc nào. Máu tuôn như suối, cánh tay kia không rút ra luôn mà nó cấm vào nội tạng thằng Lâm chọc ngoáy trong đó cho đến khi gom hết nội tạng rồi kéo ra ngoài. Đến khi mọi người đến đây thì xác của thằng Lâm chỉ còn một đóng bầy nhầy không ra hình dáng, chắc lẽ nó căm tức vì thằng Lâm đã chém nó. Thấy cái cảnh này cả xóm đã không còn sợ hãi mà chuyển sang căm thù loài quỷ dữ đã giết hại con cháu, bạn bè, hàng xóm của họ. Sự căm thù này cũng giống như căm thù bọn xâm lược dầy xéo non sông ta, đẩy con dân nước việt vào cảnh khốn cùng phải chui rút vô rừng sâu cầu mong an ổn mưu sinh. Ấy vậy mà …. Trong đám người có cả ông Trương Thuận, ông liếc nhìn người dân đang sục sôi máu quyết tâm diệt trừ loài quỷ dữ thì tức giận im lặng quay về. Về đến nhà ông đi thẳng vô trong phòng mình, sâu trong căn phòng đó có tầng hầm mà ông đã đặc biệt xây dựng lúc mới làm nhà. Trung tâm của tầng hầm là một điện thờ hình tròn, chính giữa có một bức tượng trông như mấy tượng thờ thần linh bên Xiêm, nhưng không? Ở đây ông không thờ thần linh mà là một con quỷ và chính con quỷ này đã sát hại người dân trong xóm. Thật ra cái ngôi mộ kia chẳng phải là để an táng song thân hay ông bà tổ tiên gì cả mà nó là một cái mê cung để chứa vàng bạc mà ông đã âm thầm vận chuyển từ phía bên kia biên giới về đây để cất giữ. Làm mộ chỉ là cái cớ để che mắt mọi người. Và con quỷ kia ông đã tiêu tốn rất nhiều vàng bạc để mời một ông thầy tà bên đó về đây để luyện, con quỷ này nó càng giết nhiều người thì quỷ khí của nó càng tăng, giết đủ 49 người thì coi như hoàn thành. Còn phần thân xác nạn nhân bị con quỷ kia tha về khu mộ để ông thầy tà bố trí tà pháp sau này giam giữ con quỷ trông coi kho báu. Mọi việc được bố trí rất tốt và ban đầu ông thầy tà kia đã điều khiển con quỷ giết hại những nạn nhân như vậy là để mọi người nghĩ thú dữ về xóm bắt người. Nhưng không ngờ hôm nay thằng Lâm lại chém trúng phần ngực con quỷ làm rách lá bùa khống chế, lại làm con quỷ kia bị thương nên nó mới tức giận mà phanh thây thằng Lâm ăn gần hết nội tạng. Cũng vì chuyện này mà làm dân xóm sôi sục, e là phải tạm dừng một thời gian cho dân xóm yên tĩnh lại. Ông đi tới trước điện thờ cúi người chào, rồi ông nói với người đàn ông đang ngồi xếp bằng ngồi gần đó:<br>
        A Lý làm vậy chết lỵ dồi, dân trong xóm bây giờ đang lùng sục khắp nơi tìm con quỷ a, tụi nó mà tìm tới khu mộ là chết ngộ với lỵ luôn áa.<br>
        Ông thầy A lý kia hừ một tiếng rồi trả lời:<br>
        Ông Trương yên Tâm a, mấy cái xác kia ngộ đã chuyển vô sâu trong hầm rồi. Bên ngoài có mấy lớp khoá con ruồi cũng khó mà bay vào trong. Giờ trước mắt phải cho con quỷ yên lặng một thời gian, chờ tụi nó lơ là thì mình cho nó ra tiếp. Việc này không thể gấp gáp được.<br>
        Ông Thuận thấy vậy cũng yên tâm nên gật đầu quay người trở lên trên.<br>
        Trở lại phía dân trong xóm, bác Ba cùng ông Năm đứng thầm thì chuyện gì đó một lúc rồi bác Ba quay người quay trở về nhà, còn ông Năm thì tập hợp mọi người lại cắt cử thanh niên canh gác tuần tra còn đàn ông trung niên thì ngay trong đêm đi chặt cây dâu tầm, cây mây, lấy máu chó, nước tiểu trẻ con. Bác Ba về đến nhà gom gọn mấy bộ đồ, tay chộp lấy cây mác cùng bộ cung tên băng băng vượt rừng……….<br>
        </p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('3e047cde-fef5-45ac-b4ca-c83ed9051827',
        5,
        'Chương 5',
        '9e530ef0-fc69-4f1a-a12b-803c687c006e',
        '
        <p>  Chap 5:<br>
        Mấy ngày hôm sau đó cả xóm đều hồi hợp chờ đợi nhưng chẳng có chuyện gì xảy ra. Bên phía ông Thuận thì cứ đi ra đi vào vì sốt ruột, số vàng kia đã được chuyển đến khu mộ rồi nhưng nếu không có con quỷ kia canh giữ thì xóm muộn gì cũng sẽ bị tụi trộm cướp ghé thăm. Mà cái thời buổi loạn lạc này trộm cướp rất manh động và khát máu, có khi cướp xong nó gi** luôn cả nhà để bị đầu mối. Suy nghĩ trong chóc lát ông bổng nhiên nỡ nụ cười nham hiểm, ông quay vào nhà ngó trước ngó sau rồi kêu đứa người ở:<br>
        Thằng Dương đâu? Lên đây cho Lỵ.<br>
        Thằng Dương chạy lên thì ông thủ thỉ mấy câu rồi cho nó mấy cắt bạc, ông dẫn nó đi tới cửa xuống tầng. Cửa hầm vừa mở thì ông đẩy mạnh nó xuống dưới rồi vội đóng cửa hầm lại một lúc sau thì nghe tiếng thét văng vẳng vang lên từ dưới hầm sâu. Xong chuyện ông lại đủng đỉnh đi ra, thì ra lúc nãy ông đã lừa thằng người ở là xuống dưới hầm phụ ông chuyển đồ quan trọng và thưởng cho nó mấy cắt lẻ để nó không đề phòng mà đẩy nó xuống làm mồi cho con quỷ đói kia. Mà chính vì cái hành động tàn ác này đã dẫn ông đến cái kết cục bi thảm mà ông không lường trước được. Mấy ngày kế tiếp ông lại lừa một đứa người ở khác và đẩy xuống dưới y như cái cách mà ông đã lừa thằng Dương. Vì tránh sự nghi ngờ của những đứa khác nên ông tạm ngưng mấy ngày để tìm cách, nhưng con quỷ kia từ bữa nó sát hại thằng Lâm rồi ăn hết nội tạng và hai đứa người ở thì nó đã biến đổi thành một loài quỷ hung tàn và khát máu hơn hẳn trước kia. Mấy hôm ông không cho nó ăn nên nó bắt đầu phá bùa thoát lên để đi tìm người sát hại, nó đi vào trong xóm loanh quanh một vòng mà không tìm thấy ai để bắt. Bỗng nhiên ở phía xa nó nghe tiếng nói cười của hai người đang đi về phía này, nó liền bay nhanh tới đón chặn bắt người, nhưng chưa bay được bao xa thì nó bị một mũi tên bắn xuyên qua người. Nó hú lên quái dị, quay đầu tìm kẻ nào đã bắn nó thì lần này nó gặp ngay một làn mưa tên. Trên mỗi cây tên còn có một lá bùa đang bốc cháy, mỗi lần tên phép kia bắn trúng nó liền phát ra tiếng nổ bom bóp giòn vang. Một loạt tên phép kết thúc thì tiếp theo là mấy thùng nước tiểu cùng roi mây dồn dập đập lên người nó. Lúc đầu nó còn hú hét vang động, giờ thì chỉ có grừ grừ khe kẽ rồi im bặt. Một hồi lâu không thấy động tĩnh gì mọi người trong xóm lúc này mới dám tiến lên gần để nhìn xem nó chết chưa, thì một tiếng quát của một ông bác trung niên phía sau vang lên:<br>
        Đừng đi lên, cẩn thận nó giả chết.<br>
        Ông chưa kịp nói dứt câu thì con quỷ kia bỗng bay phốc lên, do nó quá nhanh nên chẳng ai phản ứng kịp. Cả xóm định đuổi theo nhưng ông kia ngăn lại:<br>
            Mọi người cứ về nhà ông năm trước đợi tin, thằng Ba bây theo tao.<br>
        Vậy là hai người tiếp tục đuổi theo dấu con quỷ. Còn về phần ông thầy tà kia, mấy hôm nay ông luôn ở trong phần mộ để làm phép yểm mộ nên không hay mọi chuyện xảy ra, hôm nay lúc ông đang ngồi luyện như bình thường bỗng nhiên phun ra một ngụm má* rồi bất tỉnh. Đến khi tĩnh dậy thì nghe phía trong xóm có tiếng hét vang động, biết có chuyện không hay ông chạy nhanh về nhà ông Thuận. Đến nơi ông không kịp để ông Thuận hỏi thăm mà đã chạy tọt xuống tầng hầm, thấy ông lý gấp gáp như vậy ông cũng chạy theo. Xuống tới dưới thì hai người ngơ ngác, điện thờ đã bị phá tan nát. Dưới đất thì có mấy khúc xương trắng nằm lăn lóc dưới nền, chưa kịp định thần thì ông lý đã bị con quỷ kia vỗ cho một cái phun ra máu tươi bay thẳng vô vách hầm. Ông Thuận thấy chuyện chẳng lành nên quay lưng bỏ chạy nhưng con quỷ nào bỏ cho ông đi dễ dàng như vậy, nó đang đói cộng thêm mới bị dân xóm tẩn cho một trận bầm dập giờ đây nó chỉ muốn được ăn uống thiệt no để dưỡng thương. Nó chộp được Ông Thuận thì bắt đầu cắn xé ăn tươi nuốt sống trong tiếng kêu la thảm thiết của ông ấy, ông lý biết sức mình giờ không còn khống chế được con quỷ kia nên nhẹ nhàng bước ra ngoài. Vừa đi đến cửa thì bị con quỷ phát hiện, nó gầm lên rồi bay theo ông thầy tà. Nghe tiếng động cả nhà ông Thuận chạy ra coi thì thấy cảnh tượng hãi hùng mà con quỷ kia đuổi theo ông thầy tà, bà Vợ biết mọi chuyện đã không thể dấu diếm dân xóm được nữa nên hốt hoảng tìm chồng, chạy xuống tầng hầm thì bà thấy ông Thuận đã thoi thóp. Ruột lòi ra ngoài, da thịt bị cắn nham nhỡ, máu chảy đầy nền, cảm giác bị ăn thịt lúc bản thân còn sống chắc chẳng thể nào hình dung được cái nỗi đau trong đó. Bà vội chạy trở lên gom hết vàng bạc trong nhà rồi dắt theo mấy người hầu thân cận chạy về hướng huyện lỵ. Con quỷ đuổi theo một đoạn thì bắt được ông thầy tà, nó chộp một phát về phía lưng ông ta rồi xé luôn một lớp da bỏ vào trong miệng, chưa kịp ăn thì một lá bùa rực lửa bay thẳng vào mặt con quỷ. Tiếp theo là ba lá bùa bay thẳng lên đỉnh đầu nó xoay quanh một lúc thì chợt có tiếng sấm rung động không trung kèm theo đó là một tia sét đánh thẳng xuống. Con quỷ bị đánh cháy đen chỉ còn một đống bùn đen hôi hám. Ông Bác kia tiếng lên coi thì trong đống bùn kia có một tia khói bay đi rất nhanh, ông không đuổi theo mà đưa tay lên tính rồi than thở quay lại xem người kia ra sao. Ông thầy tà giờ này chỉ còn là hơi tàn, ông ta thều thào tiếng được tiếng không kể lại mọi chuyện. Riêng phần khu mộ ông dặn dò đừng cho ai đi xuống vì ông đã yểm bùa bên dưới nếu không phải người trong môn phái ông thì rất khó giải, xuống chỉ tìm đường chết. Nói xong thì ông ta tắt thở, hai người thở dài rồi mang xác ông thầy tà đặt vô nhà ông Trương Thuận châm lửa đốt đi để ngừa ma quỷ lại tụ tập do nhà này đã bị nhiễm âm khí. Ông quay lại dặn dò bác Ba mấy câu rồi đi luôn ra khỏi xóm. Thì ra hôm đó Bác Ba đi đêm băng rừng là về bên miệt Châu Đốc xưa tìm người bạn thân của tía mình, ông là  Tư Mẫn một thầy pháp có tiếng trong vùng chuyên đi trừ tà diệt quỷ cứu người. Cuối cùng thì mọi người cũng được bình yên mà sinh sống, riêng phần bác ba thì ông lại khăn gối từ giã mọi người đi về hướng mà thầy tư đã đi……<br>
        </p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('1cff7a53-71c4-41c2-9598-498a351916f9',
