VALUES ('1d9a43d3-cd54-4b85-9734-a905eaa1cc69',
        true,
        'Ma trẻ con',
        '<p>Thằng bạn tớ định kể tên là Thức, học dưới tớ một năm, tức là khoảng đầu năm hai thì nó mới được xếp vào cùng phòng ký túc. Ngoại hình cao gầy, mặt mũi tương đối thông minh, từ đầu thằng bé đã thể hiện là đứa cởi mở, vui tính, nhưng chỉ được khoảng nửa năm thì tính cách nó gần như thay đổi hẳn.</p>',
        '061460f1-45fd-40a8-b243-5da3f0f35523',
        '2025-05-06 09:15:00.000000',
        'vi');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('8a82ebae-7210-47e4-b298-545c141c6d16',
        1,
        'Chương 1',
        '1d9a43d3-cd54-4b85-9734-a905eaa1cc69',
        '
        <p>1. Ma trẻ con.</p>
        <p>Thằng bạn tớ định kể tên là Thức, học dưới tớ một năm, tức là khoảng đầu năm hai thì nó mới được xếp vào cùng phòng ký túc. Ngoại hình cao gầy, mặt mũi tương đối thông minh, từ đầu thằng bé đã thể hiện là đứa cởi mở, vui tính, nhưng chỉ được khoảng nửa năm thì tính cách nó gần như thay đổi hẳn.</p>
        <p>Đợt ấy nó ngủ rất nhiều, cứ hở ra là thấy nó ngủ, có lần rủ nó lập team chơi LOL, đến lúc vào gank rừng, đợi mãi không thấy phản hồi của support, nhìn lại thì hóa ra thằng cu đã ngủ mất, cứ ngồi nguyên trên ghế ngửa cổ ngáy.</p>
        <p>Ban đầu phòng tớ còn thông cảm cho nó vì đó là sở thích của mỗi người, nhưng đến lần cả phòng về quê, mình thằng Thức ở lại, tới khi tớ lên trước, gọi cho nó ra bến xe chở đồ vào giúp mà nửa tiếng không thấy nó đâu. Bắt xe ôm vào mới biết là nó vẫn đang ngủ, điên nhất là nó còn không khóa cửa, may mà phòng toàn người ăn ở tốt, đồ đạc vẫn nguyên vẹn. Thế là hôm sau phòng tớ họp kiểm điểm nó, không phải chửi mắng gì, nhưng ai cũng ra vẻ bức xúc lắm.</p>
        <p>Bấy giờ thằng Thức mới chịu khai, nó ngủ nhiều như vậy là do bị ma trẻ con theo. Trước tiên phải kể đến gia cảnh thằng này, bà nội nó bán hàng mã, ngày xưa bố mẹ hay gửi nó cho bà trông. Đến một dạo, trước lễ xóa tội vong nhân vài ngày, bà nó nhận nhiều đơn hàng mã quá. Trong nhà chật không còn chỗ chứa hình nhân, bà nó mới mang bớt ra ngoài hiên để.</p>
        <p>Thằng Thức 5 tuổi, không biết cái gì là kiêng kị, hơn 9h tối vẫn ra hiên đó chơi. Bà thì mải tô vẽ mắt mũi cho hình nhân trong nhà nên không để ý, nó thấy đám người giấy liền xán vào sờ mó, vạch quần vạch áo ra nhìn. Lúc đó có một con tự nhiên đổ rạp xuống đất, thằng Thức sợ bà biết sẽ chửi, nó mới cúi đầu xuống nhặt, mắt cứ liếc về phía cửa xem bà có ra không.</p>
        <p>Lúc dựng con hình nhân lên, để dựa vào cạnh đám đằng sau, thằng Thức thấy nó như bị ai đẩy ra, dựa vào là đổ. Tới lần thứ hai thì vừa định dựng lại, thằng ấy són đái khi phát hiện ra phía sau có một khuôn mặt ló ra.</p>
        <p>Nó bảo đấy là chỗ của nó, rồi chỉ cho thằng Thức đi sang bên kia mà đặt. Thằng bé kể là cái mặt nó trông thấy nhìn như đứa trẻ con, nhưng không có lông mày, không có răng, mắt với miệng đều đen xì, tóc còn ướt và trong tai chảy ra thứ nước màu lòng tôm. Nó ngồi thu lu giữa đám hình nhân, mặt ngửa lên nhìn trân trân vào mặt thằng Thức. Ngay từ lúc nhìn thấy đứa trẻ con, thằng Thức đã không còn biết gì nữa, đứa trẻ bảo nó cầm con hình nhân đi sang bên kia, đi hết hiên vẫn chưa cho bỏ xuống.</p>
        <p>Mà thằng Thức bảo đứa trẻ này mồm miệng rất cay độc, vừa đi nó vừa chửi, rủa cho nhà ông Sinh nào đó chết tiệt nòi tiệt giống, để nó nhìn thấy nó bóp cổ móc mắt cho bằng sạch cả nhà thì thôi. Thằng Thức mỏi tay định bỏ hình nhân xuống, nó lết theo đằng sau, bắt cầm lên đi tiếp, không cầm nó dúi đầu vào bụi cây tới rách mặt.</p>
        <p>Lúc đấy là đã đi đến bờ dậu nhà hàng xóm, nếu đi tiếp thì là dãy hố xí với biogas nhà bà thằng Thức. Bà nó mà không phát hiện kịp thì chắc thằng cu đã bị dìm chết dưới đấy cũng không biết.</p>
        <p>Bà thằng Thức nghe tiếng chó dộ ma, lại thấy thằng cháu không có trong nhà liền hốt hoảng lao ra sân tìm, nó kể là bà nhìn cái vệt nước chạy dài từ hiên ra sau vườn, tới lối đi giáp với nhà hàng xóm thì biến mất. Bà nó hãi quá mới chạy vào cầm con dao thái rau chuối ra, lấy đèn pin soi xuống vườn, vừa đi vừa phạt dao vào cành lá, ý là để dọa cho con ma kia sợ.</p>
        <p>Soi đến chỗ gốc cây sấu thì thấy thằng Thức đang đứng cầm con hình nhân, mặt quay vào thân cây, nói nói cái gì không rõ. Bà nó lập tức giơ tay chém phập một cái xuống thân cây, ngay cạnh đầu thằng ấy, cùng lúc giật luôn con hình nhân vứt ra. Thằng Thức bị động thì thót hết gan ruột, hai mắt u u mê mê nhìn bà nó, dưới ánh đèn pin, mặt bà nó hiện ra trắng bệch như hình nhân, làm cho thằng bé vừa khóc vừa đái ra quần.</p>
        <p>Bà thằng Thức tưởng cháu bị làm sao, vội vàng xách cổ nó đi lên nhà, thay quần áo cho, lúc đó mới thấy trên mặt thằng cu xước xác như bị cào, rất nhanh bà nó liền đoán được là đứa nào vừa làm. Ngay trong đêm hôm ấy, bà thằng Thức ra chuồng gà, bắt con gà trống, cắt cổ lấy tiết, trộn với gạo sống và đốt mấy lá bùa vàng vàng mà nhà nào có đám ma hay xin về dán vào quan tài, nhà bà nó bán cả cái đấy nên rất sẵn. Đem tro bùa và tro nhang trên bàn thờ đổ vào đĩa máu gạo, bóp cho đều, hai tay bà nó đỏ lòm những máu. Xong bà nó đem ra hiên vung, cứ vốc từng nắm mà quăng tứ phía, miệng hú:</p>
        <p>“Thằng nào con nào nửa đêm xin ăn nhà bà, bà cho gạo cho thịt ra mà ăn đi này…”</p>
        <p>Xong xuôi, bà nó tắt đèn, đóng cửa lại, rửa ráy chân tay rồi lên giường ôm thằng Thức, bảo nó không phải sợ, đứa nào động vào cháu bà là bà đánh cho tuốt xác. Cái mà bà thằng Thức trộn, trong giới nhà hòm gọi là bả máu, thì nó cũng tương tự bả chó bả chuột, chỉ khác là đối tượng hướng đến là bọn ma chết đường chết chợ.</p>
        <p>Nằm một lát, thằng Thức liền nghe thấy tiếng nhai rau ráu bên ngoài, bà nó bấm bụng cầu cho cái đứa theo thằng cháu ăn trúng bả. Ăn vào thì ma không chết, nhưng nó sẽ sợ mà trừ cái họ nhà bà ra, vì trong đấy có cả tro bát hương nhà bà.</p>
        <p>Thằng Thức đêm đó ngủ, hai mắt không khép được chặt, tới nay vẫn vậy, cứ ngủ là mí mắt chỉ khép hờ hờ, lòng trắng lộn ra quá nửa, trông như đang trợn lên. Cứ tưởng bà nó tài phép đủ để cắt đuôi con ma kia rồi, thằng Thức cũng không để ý đến chuyện cũ nữa. Ngày nó về với bố mẹ, gia đình năm người đột nhiên đón nhận hung tin</p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('5c2dea6a-8b54-4c10-9c58-4743da171d2c',
        2,
        'Chương 2 - Anh thứ bị chết đuối',
        '1d9a43d3-cd54-4b85-9734-a905eaa1cc69',
        '
        <p>2. Anh thứ bị chết đuối.</p>
        <p>Hôm ấy anh em nó cùng với mấy đứa hàng xóm rủ nhau chơi trốn tìm ở sau nhà, chỗ đó có một con mương, qua mương là dặng xoan lâu um tùm. Chơi thẳng đến tối, tới lượt cuối cùng, cả bọn đi trốn cho anh thứ nó tìm. Nhưng trốn mười năm hai mươi phút cũng không thấy anh nó đi bắt, gọi cũng không thưa. Cả bọn bảo nhau chắc anh thứ chạy hàng, bỏ bom cả đám rồi.</p>
        <p>Thế là không ai chơi tiếp, đứa nào về nhà đứa nấy, thằng Thức vào tới sân thì nghe mẹ nó hỏi anh đâu. Nó bảo anh về trước rồi, nhưng trong nhà không có, ngoài chuồng xí cũng không có, về đâu mà về. Nó lại tất tả chạy ra mương gọi, trèo cả sang rặng xoan lâu tìm, tuyệt nhiên vẫn không thấy.</p>
        <p>Tiếp theo cả nhà thằng Thức bổ đi tìm, hàng xóm biết chuyện cũng sang hỗ trợ, khi mà đã tìm khắp không thấy, họ mới nghĩ là anh nó rơi xuống mương. Mấy người lội xuống mò, nước dưới mương cao quá bẹn, buổi sáng nhìn đã không thấu được, tối đến màu nước sẫm lại, càng khó tìm hơn. Xục xạo suốt hai tiếng, đến tầm 10h đêm mà không thấy anh thứ nó, mẹ thằng Thức vẫn bình tĩnh gọi con, mong là anh thứ nó chỉ trốn đâu thôi.</p>
        <p>Nhưng có người đứng trên cành xoan lâu, nhìn xuống bờ mương thấy cái thùng phuy rỗng, trong thò ra hai bàn chân trẻ con. Vội vàng mọi người mới qua xem, thùng phuy cao hơn 1 đứa trẻ 8 tuổi, tức là cao hơn anh thứ nó, vậy mà anh thằng Thức lại lộn đầu bên trong, lúc nhấc ra người đã lạnh ngắt, từ đầu đến ngực ướt sũng nước. Thùng phuy chỉ đọng một lớp nước nông, anh thằng Thức chết do ngập đầu xuống đấy, mà lại ở tư thế lộn ngược người, thành thùng phuy cao nên không ra được.</p>
        <p>Trong đám ma, thằng Thức thấy có một đứa trẻ lạ ngồi xổm ngoài sân, mắt nhìn vào quan tài, nó cười như dại khi thấy thằng Thức nhận ra. Lúc kể với bà nội, bà nó hỏi có nhớ hình dạng đứa trẻ thế nào không, nó bảo là không có lông mày, không có răng, mắt với miệng đen xì, đầu tóc bết nước.</p>
        <p>Rất lâu sau bà nó mới nhớ ra, có một bận trong làng vớt được xác một đứa trẻ con, mấy đêm trước đi soi chuột trượt chân chết đuối dưới mương. Xác đứa trẻ đó trương lên, trong miệng còn ngậm con chuột, không biết chết trong hoàn cảnh nào.</p>
        <p>Thằng bé đó mồ côi, cái chỗ nó ở về sau là chuồng lợn nhà ông Sinh, nó thì được người làng chôn cất ngoài nghĩa địa, nhưng nhiều người vẫn nói là thỉnh thoảng trông thấy có con ma núp dưới bờ mương bắt chuột ăn. Thằng Thức kể đến đó thì sợ, anh nó tính ra là chết oan, chết trẻ khỏe ma, qua tuần đầu đã thấy anh nó hiện về.</p>
        <p>Kiểu như trong nhà, thằng Thức là đứa thân với anh nhất. Quần áo của anh nó bố mẹ vẫn còn giữ lại mấy bộ mới để nó mặc, thành thử về sau liền sinh ra chuyện.</p>
        ',
        '2025-05-01 10:17:00.000000'),

        ('50f19cbb-ef54-426e-a8a7-26681c411193',
        3,
        'Chương 3 - Bắt vía',
        '1d9a43d3-cd54-4b85-9734-a905eaa1cc69',
        '
        <p>3. Bắt vía.</p>
        <p>Tuần đầu anh thứ, sáng tinh mơ nó đã dậy theo bố mẹ đi chuẩn bị cỗ bàn đón họ hàng sang làm lễ. Lúc mà người lớn bận bịu ngoài sân thì một mình thằng Thức ngồi xúc cháo ăn trong nhà, nó ngồi đối diện với bàn thờ anh thứ, ăn cũng không được nhiều, một miếng cháo nó ngậm tới dăm phút mới nuốt.</p>
        <p>Ngoài trời vẫn còn tờ mờ tối, trong nhà bật đèn nên độ tương phản rất rõ ràng, ý là thằng Thức tuyệt đối không nhìn nhầm. Vừa ăn nó vừa nhìn lung tung, cạnh bàn thờ anh thứ là cửa sổ hướng ra sau nhà, một cánh đóng một cánh mở, bất thình lình nó nhìn thấy có khuôn mặt trắng bệch đang liếc vào trong.</p>
        <p>Thằng Thức còn chẳng nhận ra mặt người đó là ai, nhưng vì đang ngồi đối diện với bàn thờ anh thứ, nơi mà ánh nến chiếu đến cũng hiện ra khuôn mặt trắng bệch như vậy. Đang bưng bát cháo mà nó đánh đổ xuống đất, anh thứ không vào được nhà nên chỉ có thể đứng nhòm từ bên ngoài, nó còn nhỏ nên không hiểu chuyện, lúc đó tự nhiên hỏi: “Anh thứ về rồi hả?”</p>
        <p>Anh nó cứ trợn trắng mắt mà liếc về phía bàn thờ, nói như người bị sặc nước: “Áo…ọc…ọc…áo của tao…ọc… mày trả…áo cho… tao…”</p>
        <p>Cái áo mà anh thứ nói là cái sơ mi cộc tay nó đang mặc, thường thì đây đều là quần áo của anh thải lại, nhà nó cũng không kiêng kị gì mà cứ để nó mặc. Mẹ thằng Thức nghe tiếng bát vỡ trong nhà thì vội chạy vào, thằng Thức chỉ ra sau nhà, nói anh thứ đang ở ngoài đấy. Mẹ nó mở cửa sổ ra nhìn, sau nhà là rãnh nước, không có ai ngoài đó. Quay lại hỏi thì mới biết, anh thứ về để đòi áo, vì là người chết đuối nên lúc nào cũng thấy lạnh, còn mang tiếng chết đường chết chợ, có về cũng chỉ đứng được ở ngoài cửa.</p>
        <p>Bà thằng Thức biết chuyện, bảo khi sống anh em nó hòa thuận, yêu thương nhau lắm, lúc anh nó chết đi, nhà cũng cuộn chăn bọc áo đầy đủ cho anh nó rồi, vì cớ gì hôm nay lại về đòi áo. Nghĩ rồi bà cầm bó rơm, dắt theo con chó nhà thằng Thức ra chỗ thùng phuy anh nó chết. Cột con chó vào thân cây xoan lâu, xong bà nó châm lửa đốt bó rơm, tiếp theo liền hơ lửa trong thùng phuy, tay đập vào vách sắt, ầm ĩ một lúc.</p>
        <p>Con chó đang chụm vào chỗ thùng phuy tự nhiên giật phắt dây xích, nó hướng về một bên mà sủa, cứ ba tiếng lại ngừng. Bà thằng Thức dừng tay, nhìn cái hướng mà con chó đang chồm đến, bảo với người nhà về xoay bàn thờ anh thứ ra cánh trái, áp lưng vào tường, vuông góc với bàn thời gia tiên. Không để anh nó hướng mặt ra cửa nữa, thằng chết đuối vẫn lảng vảng ở gần đây nên nó thấy anh thứ về thì bắt nạt.</p>
        <p>Tới đếm hôm đấy, bà thằng Thức nằm mơ thấy anh nó về. Anh nó cứ đứng ngoài cửa khóc, vẫn mặc cái áo phông trắng với quần đùi cây dừa, bảo bố mẹ không thương con, để con chết khổ quá. Bà nó hỏi sao mày chết. Anh thằng Thức kể là bị một đứa trốn trong thùng phuy dìm chết, mà cái đứa ấy nó nhầm anh thứ với thằng Thức, cũng là do bộ quần áo của hai anh em nó mặc trên người. Khóc một lát thì có ông trung niên đến đón anh nó đi, bà nội bảo đấy là ông trẻ (em ông nội), nhờ lúc sáng chuyển hướng bàn thờ nên hai ông cháu mới nhận được mặt nhau.</p>
        <p>Bà thằng Thức có dậy ra gian thờ thắp hương, khấn vái một thôi một hồi, xong sáng hôm sau nói với bố mẹ nó phải đem thằng Thức lên chùa làm lễ. Sợ là nó với thằng chết đuối đã bắt vía nhau, trẻ con là thành phần dễ bị ma bắt nhất, nếu biết sớm mà giải thì không đáng ngại.</p>
        <p>Để trễ một chút, như trường hợp của thằng Thức, giải được vía nhưng cái dớp với người âm sẽ không hết. Cái dớp đó, hay dân gian còn gọi là duyên âm, từ đây mới thực sự bắt đầu</p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('00bc2b86-f146-42cc-a6ac-8d8516caa3b1',
        4,
        'Chương 3 - Duyên âm',
        '1d9a43d3-cd54-4b85-9734-a905eaa1cc69',
        '
        <p>4. Duyên âm</p>
        <p>Trước khi kể tiếp, thằng Thức có giải thích một chút về cơ chế của duyên âm. Người thế nào thì gọi là có duyên âm, thực chất là không phải tự nhiên một người lại bị vong ám, trước hết người đó phải trải qua ít nhất một biến cố liên quan đến thế giới bên kia trong đời. Hoặc là vô tình chứng kiến tai nạn chết người, hoặc là dự tang lễ người khác, trường hợp đặng biệt là trong nhà có người làm về tâm linh, nhưng khả năng này là bị ám cao nhất.</p>
        <p>Cái gọi là duyên, giống như giữa hai người sống tồn tại một dạng tinh thần mà chỉ hai người nhận biết được, duyên âm giữa hai người đã chết và giữa một người đã chết với một người còn sống cũng tương tự.</p>
        <p>Như anh thằng Thức với ông cố trẻ, đó là duyên âm giữa hai người chết với nhau. Nhiều người cứ nghĩ vong theo là chuyện đơn giản, nhưng mà họ có biết duyên âm giữa người sống với người chết nó khó thành như thế nào không? Nói thẳng ra thì người sống với người sống còn phải đợi 18, 20 măn mới tìm được nhau, chuyện đó giữa hai người của hai thế giới vốn dĩ đã rất mơ hồ, thậm chí còn hiếm và khó tin nữa.</p>
        <p>Mà duyên ở đây không phải là lên vợ lên chồng, duyên là kiểu hợp tính hợp nết, mới gặp đã quen. Giữa người sống với người chết thường không tồn tại duyên theo nghĩa tích cực, đúng ra là khi một người bị vong ám, đó giống như là khổ hình đối với người ấy.</p>
        <p>Mấy cái như là bị người âm sàm sỡ, rờ rẫm khắp người, xin lỗi nhưng thằng Thức nó bảo, người âm họ không cảm xúc với cơ thể trần tục, mấy chuyện như vậy họ không làm. Ngẫm ra thì thực chất những trường hợp vu oan cho người âm sàm sỡ đều rơi vào các chị em, tớ hỏi phần lớn các anh em đều chưa từng gặp sự cố nào như vậy. Tỷ lệ ma nam so với ma nữ chỉ có bằng hoặc ít hơn, ma nữ còn rất manh động, thế tại sao nó không động chạm gì đến các anh em?</p>
        <p>Theo các chị em nói, rằng thì là mà đang ngủ, có bàn tay sờ soạng từ đầu đến chân, kích thích các kiểu, vân vân. Nhưng mà cái đó được gọi là Mộng tinh, xuất phát trong vô thức của mỗi người, nam cũng như nữ, thậm chí ở phụ nữ còn mãnh liệt hơn.</p>
        <p>Các chị em có chu kỳ trong tháng, trước đó vài hôm sẽ có hiện tượng lạ, người bốc hỏa, khao khát và có nhu cầu gấp ba lần bình thường. Do cái kích thích tố trong người dâng cao, thành thử đêm ngủ mới cảm thấy vậy, chứ tớ nói thật, ma với người âm họ động chạm cơ thể các chị em làm gì?</p>
        <p>Nếu họ thích thì họ sẽ hành các chị em tới chết đi sống lại, hành là kiểu tra tấn cơ thể, người không ra người ma không ra ma luôn. Chị em nào không tin, cứ tìm hiểu những người từng bị vong ám, bị ma nhập và trúng tà xem, họ phải gọi là khổ, chứ không phải là sướng như chị em nghĩ.</p>
        <p>Đấy là cái mà tớ thấy nhiều người hay nhầm nhất, vong cũng có danh dự của họ, mà mục đích họ tiếp cận người sống thường không phải tốt đẹp gì. Xin hãy phân biệt giữa ám và phù hộ, vì có người bảo là thân nhân chết đi bám theo mình, bàn thờ trong nhà để làm gì, một năm giỗ chạp cúng rằm để làm gì, tất nhiên là ông bà bố mẹ không đi theo con cái thì đi theo ai. Nói vong ám tức là nói đến người chết đường chết chợ, chết đâm chết chém, không người thân thích, không ai thờ phụng nên mới thành ra cô hồn dã quỷ bắt người thế mạng.</p>
        <p>Kể tới đây là mọi người cũng hiểu được phần nào cái cơ chế để bị vong ám rồi, đầu tiên là phải có biến cố tạo tiền đề cho người âm xác định đối tượng, nhưng không phải ai đi đám tang hoặc xem tai nạn cũng bị như vậy. Yếu tố thứ hai phụ thuộc vào vận mạng và ý chí của người đó, hiểu nôm na thì nó là thể chất và tinh thần của một người. Cũng đừng có ai hy vọng bị người âm ám, mất mạng như chơi đấy.</p>
        <p>Thằng Thức cho rằng, trẻ con là độ tuổi dễ bị vong theo nhất, vì thần kinh bọn nhỏ không đủ vững, đúng hơn là yếu bóng vía, mạng mỏng, khả năng nhận biết chưa hoàn thiện. Lại nói chuyện của thằng Thức, con ma chết trôi ám nó về sau cũng bị chặn lại ở chùa. Nhưng dù đã giải được vía, thằng cu vẫn dính phải cái dớp với người âm, theo tử vi thì là bản mệnh của nó bị khuyết.</p>
        <p>Cắt nghĩa một cách đơn giản là sóng não của nó đặc biệt hơn người thường và có thể bắt được tần số của người âm. Tuy vậy, quá trình bắt sóng đó diễn ra rất lâu dài, như tớ nói là duyên âm vô cùng khó thành, để thực sự tìm được vong hợp vía, thằng Thức đã phải sống 12 năm khổ sở, ngang với người bị bệnh động kinh. Nó chia toàn bộ quá trình ra làm ba giai đoạn, đấy là tính từ sau cái bản lề bị thằng chết trôi dắt đi.</p>
        ',
