VALUES ('e2a8d4c2-2e2b-4176-83a8-5ae919c1faf6',
        true,
        'Chết Mất Xác',
        '<p>Tiếng chuông cửa nhà Huy cứ vang lên inh ỏi. Không biết là mới sáng sớm thế này thì ai lại bấm chuông như thế?</p>
        <p>Anh ể oải mà bước xuống giường rồi ra ngoài để mở cửa.Cánh cổng trong nhà vừa được mở ra thì một người phụ nữ ngoài 50 tuổi nắm lấy tay anh mà hỏi dồn dập:</p>',
        '061460f1-45fd-40a8-b243-5da3f0f35523',
        '2025-05-06 09:15:00.000000',
        'vi');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('a4f5edcf-6ff2-44ff-bf1e-3c675f03e491',
        1,
        'Chap 1',
        'e2a8d4c2-2e2b-4176-83a8-5ae919c1faf6',
        '
        <p>Tiếng chuông cửa nhà Huy cứ vang lên inh ỏi. Không biết là mới sáng sớm thế này thì ai lại bấm chuông như thế?<br>
        Anh ể oải mà bước xuống giường rồi ra ngoài để mở cửa.<br>
        Cánh cổng trong nhà vừa được mở ra thì một người phụ nữ ngoài 50 tuổi nắm lấy tay anh mà hỏi dồn dập:<br>
        “ Cậu…cậu…cậu cho tôi hỏi tối qua con Hằng nó có ghé nhà cậu không…?”<br>
        Huy ngơ ngác mà lắc đầu:<br>
        “ Không bác, à mà trưa qua, cháu với Hằng có ăn cơm với nhau . Sau đó thì cháu đi làm rồi Hằng bảo là cô ấy về nhà mà bác.”<br>
        Người đàn bà bù lu, bù loa mà than khóc :<br>
        “ Ấy từ trưa qua đến giờ có thấy nó về đâu. Gọi điện thoại cho nó từ tối qua đến giờ, mới đầu thì máy có rung, sau đó thì thêu bao không liên lạc với nó được…”<br>
        Huy nhăn mặt:<br>
        “ Lạ nhỉ…trưa qua ăn cơm xong thì cháu thấy cô ấy bình thường mà…”<br>
        Người phụ nữ ấy vẫn cứ khóc mà lấy điện thoại ra mà gọi cho con gái mình. Nhưng dường như bà ta tuyệt vọng vậy, khi điện thoại của con gái bà không thể liên hệ được.<br>
        Người phụ nữ mất con như gục ngã mà ngồi bệt xuống đất khóc lóc. Làm cho Huy cũng thấy cảm động.<br>
        “ Kìa bác…bác đứng lên đi…”<br>
        Người phụ nữ thấy Huy đỡ mình dậy thì vẻ mặt ngơ ngác mà nhìn anh.<br>
        Bà ta như suy nghĩ ra được điều gì mà đẩy Huy ra:<br>
        “ Là cậu….hay là chính cậu đã làm gì con gái tôi….”<br>
        Người phụ nữ tự nhiên lao vào đánh đấm, cào xé người Huy. Khiến cho anh cũng phải ra sức mà cản lại:<br>
        “ Kìa bác, cháu với Hằng quen nhau từ hồi còn cấp 2, cháu và cô ấy có mối quan hệ như bạn bè vậy thôi thì làm sao có chuyện gì xảy ra được.<br>
        Vả lại nếu có gì thì làm sao cháu dám đứng trước mặt bác mà không chút run sợ như vậy…!”<br>
        Những lời nói của Huy cũng không làm cho bà ấy ngừng khóc được.<br>
        Huy lấy hết danh dự của một thằng đàn ông mà nói:<br>
        “ Được rồi, cháu sẽ đi tìm Hằng với bác , nếu ngày mai không thấy, cháu sẽ cùng bác khai báo công an…”<br>
        Huy không nói nhiều mà trở vào trong nhà khoác tạm chiếc áo khoác và dắt chiếc xe máy ra ngoài. Anh nhìn mẹ của Hằng mà nói tiếp:<br>
        “ Cháu sẽ đưa bác đi tìm Hằng.”</p>
        <p>Giờ này là hơn 7 giờ sáng, ấy cho nên là quán cơm, bún, phở mang bảng hiệu Ngọc Ý rất đông khách.<br>
        Một tô bún với giá bình dân 20k mà đầy ấp thịt khiến cho những người dân lao động của cái xã này thường xuyên đến quán mà ăn. Dù bún hay phở hay cơm trưa đều rất rẻ khiến cho khách khó tính nhất cũng phải ưng cái bụng.<br>
        Một người đàn ông đã gần 60 tuổi, mặc đồ bảo vệ , đứng trước tủ kính đựng xương thịt của cô chủ quán mà chỉ chỏ:<br>
        “ À miếng xương này nạc nè, cái miếng thịt này ngon nè, gắp cho tôi…”<br>
        Lão lúc này cũng vậy, khi nào cũng chỉ bảo cô chủ Ý gắp cho bát phở mình miếng ngon.<br>
        Mặt của Ý có vẻ khó chịu vì người đàn ông đòi hỏi này, nhưng cô vẫn nghĩ khách hàng là thượng đế vậy.<br>
        Lão nhìn bát phở rồi lại hỏi:<br>
        “ Thế bán nhiều thịt thế này lỗ thì sao?”<br>
        Ý mỉm cười mà lau đi giọt mồ hôi trên trán:<br>
        “ Lỗ làm sao được hả chú. Quán con trước giờ là vậy, muốn là con thêm thịt , thêm xương. Nên chú thấy quán lúc nào cũng đông khách mà!”<br>
        Ông chú cười hài lòng mà bưng bát phở ra chỗ cái bàn mà ngồi xuống ăn khen tới tấp.<br>
        Đúng vậy, Ý không hề tiếc với ai những gì, cô bỏ thêm thịt vào mà bưng cho khách khiến ai cũng thích.<br>
        Hôm nay cô bán hết số bún đã lấy nên vui mừng mà cười tủm tỉm.<br>
        Ý bước đến bên cái tủ lạnh mà mở cánh tủ ra mỉm cười mà nói:<br>
        “ Thịt nhiều như thế này…bán rẻ cho khách cũng không tiếc mà!”</p>
        <p>Có tiếng xe máy đến, Ý vội đóng tủ mà bước ra ngoài xem. Cô thấy người yêu cô là Huy cùng với một người phụ nữ bước vào.<br>
        Cô mới tiến đến, chưa kịp hỏi thì Huy đã nói:<br>
        “ Đây là mẹ của Hằng, Hằng từ đêm hôm qua đến nay chưa về nhà nên anh phải đưa bác đi tìm. Em xem còn gì lấy cho bác ăn với nhé.”<br>
        Nét mặt của Ý hơi thay đổi, cô hỏi lại:<br>
        “ Thế anh ăn gì chưa?”<br>
        Huy lắc đầu mà nhìn Ý, cô cũng nhìn anh rồi nói khẽ:<br>
        “ Để em lấy cho cả anh ăn,”<br>
        Huy đi lại chỗ người phụ nữ trấn an bác ta vài câu.<br>
        Ý nhìn mà nổi cáu, cô tiện tay lấy mấy miếng thịt ngon mà bỏ vào bát của người phụ nữ ấy. Miệng nhếch lên mà mỉm cười, cái nụ cười đểu rả, sở Khanh mà không ai thấy.<br>
        Tay bưng hai bát phở ra mà nói:<br>
        “ Bác và anh ăn phở nhé, bún thì dễ nuốt. Nhưng nay con hết sớm bún nên hai người ăn tạm phở nhé.”<br>
        Người phụ nữ nói khách khí vài câu nhưng rồi cầm đũa thì nước mắt bà lại trào ra mà không nuốt nổi gắp phở.<br>
        Hai người khuyên dữ lắm thì bà ta mới ăn được một ít.<br>
        Ý sau khi nghe lại những gì Huy kể, cô mới nói:<br>
        “ Tối qua thì Hằng có đến quán con ăn cơm, cô ấy đi với một cậu trai trẻ , ăn xong rồi hai người rời đi. Không chừng cô ấy đi với cậu ấy cũng nên.”<br>
        Mẹ của Hằng hỏi dò rối rít, nhưng rồi cũng không tìm được chút manh mối nào.<br>
        Huy thì sáng giờ chưa ăn nên đói bụng, ăn một lúc hai bát phở. Đến khi còn vài gắp thì ăn lấy đũa mà khều lên cộng tóc vàng trong bát phở mà đưa ra trước mặt Ý:<br>
        “ Em cần để ý này, chứ khách mà thấy thì khó nói chuyện lắm đấy.”<br>
        Vẻ mặt của Ý tái xanh đi, cô lo sợ điều gì đó sẽ bị bại lộ. Liền trả lời qua loa cho xong chuyện.<br>
        Hai người rời quán Ý mà tiếp tục đi tìm kiếm, chỉ hy vọng là sẽ thấy Hằng. Mong rằng cô ta đang vui chơi nơi nào ấy mà quên lối về.</p>
        <p>Ý dọn rửa đống bát, cô hốt hoảng, vội nhặt lên một cái móng tay nơi đáy của một bát bún mà vứt nó xuống chỗ thoát nước, miệng lẩm bẩm:<br>
        “ Không được, hôm sau phải cẩn thận hơn mới được.”</p>
        <p>Hai người ròng rã đi hết chỗ này đến chỗ kia mà vẫn không thấy Hằng đâu.<br>
        Không có một chút hy vọng nào cả, bây giờ cũng chưa đủ 2 ngày để mà trình báo công an nên chỉ biết mà đi tìm vậy thôi.</p>
        <p>Buổi trưa thì khách cũng đến lai rai mà ăn cơm quán của Ý.<br>
        Thực đơn hôm nay có thịt kho hột vịt, thịt nướng và cá kho. Có canh bí hầm thịt bằm và xương rất ngon.<br>
        Mọi người vào ăn đều khen thịt kho với thịt nướng hôm nay ngon, bảo Ý vớ được con heo ngon.<br>
        Mọi người đi hết thì cô mới rời quán mà mua một hộp cơm ở quán khác mà ăn.<br>
        Đang ăn thì có một vị khách đến, cô lấy cơm thịt kho cho khách rồi vào múc bát canh.<br>
        Mới múc lên muôi đầu tiên mà Ý đã không kìm được mà bỏ cả nồi canh thơm phức chạy thẳng ra nhà vệ sinh mà nôn mửa. Vì thứ cô mới múc lên từ nồi canh là cái ngón chân cái. Cái ngón chân còn nguyên móng đã chín , lột hết da chân và các cơ thì đã co lại.<br>
        Biết khách đang chờ nên Ý chỉ có thể nhanh chóng vào múc bát canh bí cho khách.<br>
        Cô lại vứt bỏ cái ngón chân cái ấy xuống lỗ thoát nước , quay lại bàn cơm nhìn cái hộp cơm của mình mà không muốn ăn. Nên lại vào trong bếp mà rửa chén bát.</p>
        <p>Đến tối, Huy và người phụ nữ ấy quay lại.<br>
        Ý cũng bưng ra cho hai người hai phần cơm để ăn.<br>
        Huy nhìn bát canh bí mà hỏi Ý.<br>
        “ Nay em hầm với đầu heo hay sao mà có cả mắt vậy?”<br>
        Ý gật đầu mà đáp:<br>
        “ Đúng anh, con heo này mắt hơi to nên em đã cắt ra một ít , anh ăn đi cho bổ.<br>
        Huy gắp lấy con mắt đã bị bổ ra chỉ còn con ngươi màu đen và phần ít màu trắng. Bỏ vào miệng.<br>
        _phọt_ một tiếng, Huy nhắm mắt mà thưởng thúc con mắt nó ngon đến cỡ nào.<br>
        Anh hài lòng khi thịt hôm nay nó dai dai, ngọt và rất ngon nên ăn hết dĩa cơm , húp sạch bát canh bí mà xoa xoa cái bụng.<br>
        Mẹ của Hằng cũng phải ăn vài miếng để có sức mà tiếp tục mà tìm con.<br>
        “ Thôi…bác về nghỉ đi, dù gì mai mình cũng phải tìm. Không thấy sỹ thì phải nhờ đến công an.Bác phải giữ sức khỏe để mà tìm cô ấy. Chứ cả ngày nay mệt rồi!”<br>
        Ý khuyên răn mẹ của Hằng, bà ta chịu đồng ý mà để Huy đưa về nhà. Nhưng khi Huy vừa rời đi thì bà ta cũng mở cửa mà đi tìm con gái, với bà lúc này một giây phút đối với bà rất quan trọng, lơ là một giây có khi lại gặp được con của mình thì sao .<br>
        Nên mặc kệ bóng đêm và những cơn gió thổi , người phụ nữ ấy vẫn lang thang trên khắp nẻo đường mà tìm cho bằng được con gái của mình.</p>
        <p>Ầm vang một tiếng, Ý giật mình ngồi dậy , cô thấy Huy vẫn bên cạnh mình nhưng dưới nhà bếp có tiếng thứ gì đã rơi xuống đất.<br>
        Ý mở hết điện rồi đi xuống dưới nhà. Cô ngạc nhiên khi tất cả các túi thịt mà chiều nay cô đã xếp gọn trên ngăn đông đều đồng loạt rơi xuống đất.<br>
        Ý lẩm bẩm chửi bậy mà phải xếp lại vào tủ.<br>
        Gió từ đâu thổi qua gáy của cô khiến cho toàn bộ da gà của Ý dựng hết lên, sống lưng như lạnh buốt mà khiến cho tim cô đập mạnh.<br>
        Ý ná thở mà đứng im tại chỗ, vì lúc này đây cô đang nghe thấy tiếng bước chân của ai đó đi qua đi lại trong khu nhà vệ sinh gần bếp.<br>
        Tiếng guốc cao gót cứ lục và lục cục mà bước đi trên nền gạch.<br>
        Khiến cho Ý tò mò mà đưa mắt vào đấy.<br>
        Trên tay cô túi thịt vẫn đang cầm và cánh tủ cửa lạnh cũng đang mở.<br>
        Mắt cô nhìn vào căn nhà vệ sinh đang mở rộng cửa và bóng đèn không biết là ai đã mở.<br>
        Một cái bóng dáng đi đôi cao gót mà cứ đi qua, đi lại. Chiếc áo màu xanh nhạt đẫm máu đỏ tươi cùng chiếc quần màu trắng cũng đã thấm đỏ vài giọt máu đi qua đi lại trong nhà vệ sinh.Mái tóc nó ngang vai nhưng che kín cả khuôn mặt đang cúi xuống đất mà cứ đi qua đi lại trong nhà vệ sinh.<br>
        Ý chợt há hốc miệng mà trợn tròn mắt khi cô nhận ra hình bóng ấy là Hằng, phải chính là Hằng. Cô ta đang đi qua đi lại trong nhà vệ sinh mà cúi đầu, tóc tai rũ rượi.<br>
        Ý lúc này như người mất hồn mà đứng đờ đẫn ra đó, cô đang mở miệng nhưng cổ họng như bị chặn lại mà không hét lên được tiếng nào.</p>
        <p>“ Ý…Ý… đêm hôm rồi còn đứng ngây ra đó là gì vậy em?”<br>
        Giọng nói của Huy kéo cô về hiện tại, người của cô có thể cử động được và miệng có thể mở miệng nói.<br>
        Thấy vẻ mặt sợ hãi của Ý thì Huy cũng bước đến mà hỏi han:<br>
        “ Em sao đấy? Sao vẻ mặt tím tái vậy?”<br>
        Ý ấp úng mà đưa ra cái cớ:<br>
        “ Con chuột…con chuột…”<br>
        Huy mỉm cười mà xoa xoa đầu cô:<br>
        “ Thôi cất thịt rồi ngủ đi em . Mai còn bán sớm, tưởng gì, em mà cũng sợ chuột nữa hả.?”<br>
        Ý ngập ngừng mà quay lại phía nhà vệ sinh, cô lại tiếp tục hoảng sợ khi thấy cánh cửa nhà vệ sinh đã đóng và bóng điện trong đấy cũng đã tắt tối đen như mực.</p>
