INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time, language)
VALUES ('a97855e5-2f3d-4f13-9f85-8858b2dcab03',
        true,
        'Ngãi Miên-(Ngãi Ăn Thịt)',
        '<p>Chào mọi người thì nay em mang đến câu chuyện về bùa ngãi,thường ngãi thì ai cũng biết là một cái gì đó ma quái và kinh dị nhưng câu chuyện này nó còn hơn thế.</p>
        <p>Vào năm 2005 thì trong xóm có một tiếng thét vang lên, ai nghe cũng giật mình và chạy lại thì thấy cái cô gái kia đang ôm xác con gái của mình( nghe kể lại rằng là ruột gan với tim…nó rơi ra và lòng thòng).</p>',
        '061460f1-45fd-40a8-b243-5da3f0f35523',
        '2025-05-06 09:15:00.000000',
        'vi');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('74e2d51c-2a9d-4bf1-bccc-01eac97ff4cc',
        1,
        'Chương 1',
        'a97855e5-2f3d-4f13-9f85-8858b2dcab03',
        '
        <p> #1 Ngãi Miên-(Ngãi Ăn Thịt)<br>
        (Khơi Nguồn-Thỉnh Ngãi Về Thơ và Nghiệp Báo phải trả )<br>
        Chào mọi người thì nay em mang đến câu chuyện về bùa ngãi,thường ngãi thì ai cũng biết là một cái gì đó ma quái và kinh dị nhưng câu chuyện này nó còn hơn thế.<br>
        Vào năm 2005 thì trong xóm có một tiếng thét vang lên, ai nghe cũng giật mình và chạy lại thì thấy cái cô gái kia đang ôm xác con gái của mình( nghe kể lại rằng là ruột gan với tim…nó rơi ra và lòng thòng ).<br>
        Mọi người mới biết đây là  Thắm ,nó là con dâu của bà 2 Lí ở ngã ba nên chạy lại hỏi thăm và đưa chị Thắm với con chị về nhà. Mà tội chị Thắm này cha mẹ ruột và chồng vừa mất cách đây không lâu thì tới lượt đứa con gái 3 tuổi ,nghe đâu là có mang thai thêm một đứa mà mới có 6 tháng là cái thai bị hư nữa.Ai nghe tới chuyện này vừa thấy tội nghiệp vừa thấy sợ…<br>
        Sau này tới năm 2006, thì có một anh tên là Tân đi ruộng về và đi qua một cái nhà hoang( nhà này là một cái nhà kho mà bỏ cũng lâu rồi ) thì anh ta vô tình nhìn thấy đôi bàn chân treo lơ lửng, cảm giác lúc này muốn té đái lắm rồi, sợ quá sợ mà vừa chạy vừa la “Má ơi , có người treo cổ kìa…Cứu cứu với “.<br>
        Hàng xóm gần đó nghe được chạy tới xem(1 phần quan tâm và 10 phần nhiều chuyện) thì mới biết đây là chị Thắm.Người thì điện cho bên công an xuống người thì chạy đi báo cho bà 2 Lí nghe tin này…Xong vụ này thì mọi người cứ nghĩ là chắc Thắm buồn chuyện gia đình ( cha mẹ ruột mất , mất chồng , mất 2 đứa con thì ai chịu nổi).<br>
        Mà đáng thương là bố chồng của chị Thắm thì mê tín nên không muốn chở xác con dâu về nhà, nên kêu bên công an đưa nó về nhà nó đi, mà nhà của chị Thắm còn ai đâu chỉ còn căn nhà lạnh lẽo ấy thôi…mẹ chồng chị Thắm thấy vậy cũng tội nhưng không làm được gì chồng mình nên cũng lén góp ít tiền để cho con dâu mình có cái đám có cái nguyệt để an nghỉ.<br>
        Lúc này diễn ra đám ma của cô Thắm thì có mời một sư thầy về ( sư này rất là cao tay ) vừa bước vô nói “Gia chủ này có rất nhiều tội ác và thỉnh ma quỷ về để tôn thờ” . Nghe thầy nói thế mọi người trong xóm ai nghe cũng hoang mang , có anh kia vạ miệng nói”Thấy nhà chị Thắm tốt lắm mà ta , còn thân thiện với mọi người nữa” .Thầy thấy vậy nói “ Giờ tôi thấy là có 5 vong linh đứng ở trên cái hòm của nữ này,còn có một vong mà chưa thành hình nhưng Ác Khí nó nặng lắm ! “.<br>
        Xong thầy đọc kinh và dùng chuỗi hạt đang đeo tách ra rồi ném lên trời, mọi người trong xóm đều thấy rõ ràng là hạt chuỗi tách ra và văng lên trời khi mà rơi xuống thì nó xiết lại một cái gì đó. Thầy nói lớn “Sao con lại quậy như vậy ? Có nỗi Hận gì sao ? Nói Thầy nghe thầy sẽ giúp con”<br>
        Mọi người ở ngoài chỉ thấy sư thầy gật đầu gật đầu…mà cảm giác lúc đó ớn lạnh lắm.<br>
        Sau vài phút thì sư thầy mới nói “Đúng như thầy nói là gia chủ này quá tàn ác! Lấy bào thai của cháu mình đi làm phép dẫn để câu ngãi về phù hộ làm ăn mà không ngờ bị ngãi nó hại chết không chừa một ai, tội là tội chồng của nữ này bị liên luỵ”.<br>
        Ai nghe đến cũng hốt hoảng và hỏi vậy oan hồn của bé đó thì sao thầy. Thầy nói là dẫn bé này về tu đạo để tránh hại người, dù Hận của bé lớn nhưng lại nghe lời, chỉ trả thù người hại nó” ,Thầy nói xong thì cũng niệm kinh và làm chỉnh chu cho buổi lễ.<br>
        Lúc thầy ra về thì có nói hàng xóm là hạn chế giết động vật gần nhà của nữ này để tránh cây ngãi (có quỷ già) trong đó nó hấp thụ. Do con quỷ này cao tay hơn thầy nên thầy chỉ tạm phong ấn nó đừng cho nó ra khỏi vùng nhà mà phá làng thôi. Nghe thế ai cũng rén nên từ sau cái đám ma đó không ai dám bước vô vườn nhà của chị Thắm này,lâu lâu nghe kể “Khi đi làm ruộng hay mấy đứa nhóc đi chơi về thì đều thấy 3-4 người mặc đồ trắng tay chân bị xích lại và thấy một ông già có 4 cây nanh lấy roi dây đánh 3-4 người đó, ai thấy đều sợ hết..nhiều khi có vài người thấy xong bệnh nặng hoá điên dại”.<br>
        -Hết- (1)</p>
        ',
        '2025-05-01 10:16:00.000000'),

        ('fecaf94d-b2f8-44bf-ae20-a9734146f991',
        2,
        'Chương 2',
        'a97855e5-2f3d-4f13-9f85-8858b2dcab03',
        '
        <p>Truyện Kinh Dị<br>
        #1 Ngãi Miên (Ngãi ăn thịt người)<br>
        Kết :“Quá trình thỉnh ngãi và dùng bào thai của con mình làm bùa dẫn”<br>
        Em có kể sơ qua câu chuyện về gia đình chị Thắm rồi ,giờ em sẽ kể tiếp phần Thỉnh Ngãi của ông 4 là cha ruột của chị Thắm nhé mọi người.<br>
        Này em cũng được nghe mọi người trong vùng và sư thầy kể lại .<br>
        Vào cái năm 2002 thì chị Thắm lấy chồng và có bé Mén.Sau hơn mấy năm chờ thì Mén cũng được 3 tuổi thì chị Thắm có bầu là một bé trai 6 -7 tháng,mọi thứ đều bình thường cho đến khi mà cha của chị Thắm này là ông 4 đi qua Trà Vinh chơi ( vì đây là nhà bạn của ông 4) thì bắt đầu có những biểu hiện lạ trong gia đình.<br>
        Cảm giác như là ông 4 thay đổi kiểu lạnh lùng và mặt thì không có sức sống,có vài lần ông 4 hỏi em bé trong bụng chị Thắm mấy tháng rồi, thì chắc chị Thắm nghĩ là cha quan tâm nên trả lời ,Mà ổng cứ hỏi hoài hỏi hoài…<br>
        Cho đến một hôm thì ông 4 có pha thuốc gì đó rồi nói này thuốc bổ thai , cho chị Thắm uống.Sau khi uống thuốc xong thì có nghe mẹ chị Thắm kể lại là “ Thắm nằm cứ la lên (má ơi , con đau bụng quá, Má ơi ) “ . Thấy vậy bà 4 chạy sang phòng con Thắm thì chồng nó đang cố gắng bồng nó đi bệnh viện để cấp cứu,Mà nhà cô Thắm lên bệnh viện cũng xa lắm. Nhưng may là lên kịp và khám thì bác sĩ nói là do cô Thắm ăn uống sao mà bị viêm đường ruột nên ảnh hưởng đến cơ thể và thai nhi. Sau thời gian thì bác sĩ cũng siêu âm cho chị Thắm để coi em có bị ảnh hưởng nghiêm trọng không !<br>
        Lúc này bà 4 với chồng chị Thắm chết lặng ! Còn bác sĩ thì hoang mang.Bởi vì em bé 6-7 tháng mà không có tay chân gì cả chỉ có đầu với cái thân như cục máu….Đâu ai dám kể cho chị Thắm nghe.Được vài hôm nằm viện thì cơn đau bụng lại tới và rồi chuyện gì đến cũng đến! Thai Nhi giữ không được nên bác sĩ phải gắp ra để bảo đảm an toàn cho chị.<br>
        Nghe mà đau đứt từng đoạn ruột,nhưng buộc phải làm thôi…<br>
        Khi gắp thai nhi ra thì chồng của chị Thắm hay mẹ của chị Thắm xin bào thai về mai táng cho bé nó.Bác sĩ cũng đồng ý và cho chị Thắm nằm viện sau thời gian rồi xuất viện. Mà chị Thắm từ khi ra viện thì sắc thái của cô yếu lắm và tâm trí không bình thường…lâu lâu la lên “Má ơi ! Chồng ơi..! Con em đâu rồi ? Thằng con em đâu rồi..”.<br>
        Hàng xóm đi làm đều ngang nhà này đều nghe …thấy xót lắm , thương lắm.<br>
        Nhưng mà trước lúc chị Thắm xuất viện thì mẹ chị có làm đám mời sư về tụng cho bào thai. Bà 4  định hoả thêu nhưng ông 4 can lại rồi nói “chôn đi đừng hoả thêu, uổn lắm “ . Nghe cái câu uổn lắm thì bà 4 giật mình, nói sao mà ông này nói chuyện lạ vậy,mà bà 4 cũng nghe theo nên chôn cháu ở góc vườn sau nhà. Mà có ai biết là sau khi lắp mộ thì mấy hôm sau thấy mộ bị bới lên mà không thấy xác. Bà 4 thấy lạ lạ nhưng bà ngỡ là thú hay chó nhà ai bới đất,xong bà 4 đi vòng vòng ở sau vườn để kiếm lại cái xác của cháu thì thấy mỗi cái đầu nằm ở bụi hoa cỏ ( này là do lúc ông 4 đi Trà Vinh mang về).Bà 4 hét lên !Trong xóm nghe đến ai cũng giật mình mà chạy lại hỏi,Thì bà 4 kể lại cho hàng xóm nghe.<br>
        …Sau vụ việc đó xảy ra thì mọi người cũng phụ bà 4 chôn xác cháu lại.<br>
        Được vài hôm thì thêm tin chấn động nữa là chồng của chị Thắm đi qua vườn đâu á xem thì bị tai nạn xe chết mà nát cái thân luôn còn mỗi cái đầu. Đau thương lại đau thương,chị Thắm mới trước mất con mới chấn chỉnh tâm lí lại mà giờ thêm chồng mất…thì cả người tinh thần mạnh lắm cũng hoá điên.<br>
        Ai trong xóm đều thấy chị Thắm lúc nào cũng nói chuyện một mình “Nào là con đói không ? Cho con uống nè” “Chồng ơi ,con nó đói nè “…<br>
        Một phần thì ai cũng tưởng chị Thắm hoá điên nhưng vài người cũng biết là có xảy ra tâm linh nên người ta không dám phán xét.<br>
        Cơ mà đau thương cứ đến với chị ! Ông 4 với bà 4 không biết bị gì mà chết kì quái lắm.Thấy rõ ràng là ông 4 chết mà con mắt lòi ra lưỡi thì không còn mà tay thì cầm con da!o dính má!u, còn bà 4 chết là do bị ông 4 đâ!m.<br>
        Sau cái đỉnh điểm năm 2005 thì con gái chị Thắm chết là cái câu chuyện trước em có kể ! Nhưng không biết nguyên do vì sao mà nội tạng em bị trào ra như vậy….năm 2006 thì chị Thắm treo cổ chết( em có kể qua rồi nên nhắc lại ạ)<br>
        Mãi tới giờ thì mới biết là ông 4 thỉnh Ngãi về thờ.Nên mới xảy ra vụ việc như vậy…<br>
        Theo một người quen có nói “ Chắc do ông 4 muốn cầu tài cầu lộc gì đó mới thỉnh ngãi về thờ như vậy “.<br>
        -Hết-<br>
        </p>
        ',
        '2025-05-01 10:17:00.000000');


