INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time, language)
VALUES ('3f04f812-2977-4f62-b233-29f4fc99fddb',
        true,
        'Tiếng khóc đêm trăng',
        '<p>Tôi nhớ buổi chiều đó, vừa đi học về đã thấy má chuẩn bị rất nhiều quà chất lên xe. Khỏi cần hỏi má, tôi cũng biết đó là những hộp bánh trung thu, mà bà nội và má cất công đi chọn lựa mấy ngày hôm nay, để ngày mai cả nhà tôi về quê thăm ông bà ngoại.</p>',
        '061460f1-45fd-40a8-b243-5da3f0f35523',
        '2025-05-06 09:15:00.000000',
        'vi');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('2c3318cd-ab84-4e9c-87be-5a3ece28e0e6',
        1,
        'Chương 1',
        '3f04f812-2977-4f62-b233-29f4fc99fddb',
        '
        <p>TIẾNG KHÓC ĐÊM TRĂNG 1<br>
        ———————————————-</p>
        <p>Tôi nhớ buổi chiều đó, vừa đi học về đã thấy má chuẩn bị rất nhiều quà chất lên xe. Khỏi cần hỏi má, tôi cũng biết đó là những hộp bánh trung thu, mà bà nội và má cất công đi chọn lựa mấy ngày hôm nay, để ngày mai cả nhà tôi về quê thăm ông bà ngoại.</p>
        <p>Nội vẫy tôi lại, xoa xoa đầu tôi rờ rờ sợi dây trên cổ, được kết bằng sợi chỉ đỏ do ông ngoại tặng. Nội nhìn tôi mỉm cười hiền từ, nói.</p>
        <p>“ Chà, nhanh thiệt chớ. Mới ngày nào con còn đỏ hỏn nội bồng trên tay, vậy mà bây giờ đã sắp hết tuổi mụ đỡ rồi. Cháu nội, lớn thiệt rồi đó.”</p>
        <p>Vừa nói nội vừa vân vê sợi dây trên cổ, tôi không biết nó có nghĩa gì, chỉ biết, khi tôi nhận thức được mọi việc xung quanh, đã thấy nó nằm trên cổ tôi từ hồi nào không hay.</p>
        <p>Tôi nhoẻn miệng cười, sà vào lòng nội nũng nịu như hồi lên 5, lên 6.. cười khúc khích thích thú, tôi rất thích cảm giác này, mỗi khi ở bên cạnh nội.</p>
        <p>Nội vỗ vỗ vai, nói tiếp:” Ngày mai, về quê cho ông bà nội hỏi thăm sức khỏe ngoại nghen con, nhắn ngoại khi nào ông con bớt bệnh, nội về thăm ngoại sau nhen con.”</p>
        <p>Tôi sìu mặt, nói với nội:” Ủa con tưởng cả nhà mình cùng đi mà nội? Nội cũng hứa về quê ngoại chơi rồi mà. Nội ở lại, sẽ mất vui đó ạ.”</p>
        <p>Nội cười hà hà.. an ủi tôi:” Thôi, cho nội thất hứa lần này heng. Ông con mấy bữa nay ho nhiều quá, nội sợ đi xa bệnh của ông trở nặng thêm.”</p>
        <p>Tôi rúc đầu vào nách nội, nội đã nói vậy thì cũng đành chịu, mặc dù tôi vẫn muốn cả nhà tôi về quê thăm ngoại. Chỉ là sức khoẻ của ông nội không cho phép.</p>
        <p>Tối hôm ấy, tôi háo đi ngủ thật sớm, nôn nóng tới sớm ngày mai thức dậy. Trung thu năm nay may mắn đúng dịp cuối tuần, hồi sáng ba tôi có gọi cho cô chủ nhiệm, xin cho tôi nghỉ một ngày thứ 7, để về quê. Trong bữa tối má cũng có dặn, sáng mai 3h sáng xe sẽ xuất phát, cần đi ngủ sớm kẻo mai lại dậy không kịp.</p>
        <p>Nằm trên giường, tôi nhớ tụi thằng Sếu, thằng Bình và thằng Long, ah cả nhỏ Thương và con bé Đẹt ở kế nhà ngoại. Tụi nó quý tôi lắm, mỗi lần tôi về quê là cả đám kéo nhau qua nhà ngoại, rủ tôi vào vườn trái cây, đi bắt ve, bắt dế.. chơi bắn bi, có lần còn đi mò cua bắt ốc. Tuần trước, tôi đập con heo đất lấy tiền tiết kiệm, tôi nhờ má chở đi mua mấy cái lồng đèn đem về quê tặng mỗi đứa một cái. Nói thật, rước đèn trung thu không ở đâu vui như quê ngoại, đã có lần tôi cũng được ba má đưa về đúng dịp trung thu, hồi tôi học năm lớp 5. Năm đó, tụi tôi cầm đèn đi khắp xóm, chơi bịt mắt bắt dê, chơi trốn tìm, chơi rồng rắn lên mây dưới bầu trời trăng sáng vằng vặc đến tận khuya mới chịu về ngủ.</p>
        <p>Những khoảnh khắc bình dị ấy không phải bất cứ nơi đâu cũng có, nhất là một đứa trẻ sinh ra và lớn lên ở thành phố như tôi. Cảm xúc khi ấy, khó tả lắm.</p>
        <p>Tôi mỉm cười, hai tay đặt trên bụng, đôi mắt nặng trĩu dần chìm vào giấc ngủ. Đêm nay tôi mơ.. một giấc mơ kỳ quái. Tôi thấy mình đang chơi trong sân nhà ngoại, thằng Bình và thằng Sếu đến rủ tôi đi chơi, trên tay hai đứa nó là cái nơm úp cá và cái giỏ tre đeo bên hông.</p>
        <p>Thằng Bình vỗ vỗ tay vào cái nơm, nhoẻn miệng cười nói với tôi:” Ê.. Nam! Đi úp cá cùng tụi tau hông mầy?”</p>
        <p>Thằng Sếu đứng bên cạnh phụ hoạ:” Đi đi, vui lắm ah nghen! Biết đâu bữa nay tụi mình trúng mánh, trưa có món cá nướng cuốn bánh tráng không chừng.”</p>
        <p>Khỏi phải bàn, tôi khoái nhất món ấy ở quê ngoại, nghe hai đứa nó rủ rê đi, vừa được chơi vừa có cá ăn dại gì không đi, hơn nữa ở nhà cũng buồn, chẳng có ai chơi cùng.” ừa, chờ tao chút, tao vô nói ngoại một tiếng, kẻo ngoại đi kiếm. “ tôi quay vào nhà, xin phép ngoại xong tôi thay bộ đồ bà bà màu lâu mà thím mua tặng tôi năm ngoái. Cột chiếc khăn rằn trên đầu trông tôi giống một anh nông dân thứ thiệt. Lúc quay ra, hai đứa nó nhìn tôi cười lắc lẻ, chạy lại, vỗ vai tôi rồi bảo.</p>
        <p>“ Coi bộ, mầy giống nông dân hơn là công tử mặt trắng trên thành phố rùi đấy. Thôi, đi nhanh kẻo nắng, người lớn rầy la bây giờ.”</p>
        <p>Ba thằng chúng tôi chèo thuyền đi sâu vào một con rạch, hàng dừa nước mọc san sát nhau hai bên bờ. Tháng 8 đúng mùa nước nổi, con nước lên cao, thằng Sếu rẽ mái chèo nhanh thoăn thoắt, chẳng mấy chốc hai đứa nó đưa tôi đến một cồn đất không cao lắm, nằm sâu trong cù lao, thằng Sếu khựng tay lái, hối tôi leo lên bờ trước, tụi nó cột thuyền vào gốc dừa, leo lên sau.</p>
        <p>Tôi hỏi:” Ủa, rồi nước đầy như vầy, úp cả kiểu gì? Tau tưởng chỗ nào nước nông mới có nhiều cá chớ..?”</p>
        <p>Thằng Bình vỗ ai, đáp:” Yên tâm, ở đây ít người đến lắm, đảm bảo cá cua đầy mương cho mầy coi.”</p>
        <p>Chúng tôi đi vào cồn đất, xa xa là căn nhà lá hoang bỏ trống, tôi đoán đã lâu không có người đến ở nên trông nó khá cũ, mục nát, đằng trước cỏ dại mọc đầy, nhìn kỹ có vẻ hơi ma mị rờn rợn.</p>
        <p>Tôi chỉ tay vào căn nhà lá, hỏi thằng Sếu:” Sếu, nhà ai bên kia..?”</p>
        <p>Thằng Sếu nhanh tay gạt cánh tay tôi xuống, nó nhìn tôi, rồi lại len lén liếc qua căn nhà lá, vẻ mặt lạnh tanh không cảm xúc, đưa ngón tay lên miệng suỵtttt…dài một tiếng, nhỏ giọng căn dặn:” Đừng hỏi gì, cũng đừng nhìn vào nhà đấy. Mầy cứ nghe tau là được. Còn vì sao, khi nào về nhà tau nói cho bây bít heng.”</p>
        <p>Đi sâu hơn một chút, con mương hiện ra trước mắt, con mương này không đầy nước như kênh rạch, chỉ có điều bị những nhánh cây bình bát và cỏ dại chỉa ra, che gần kín. Thằng Bình khom người bẻ mấy nhánh bình bát ném lên bờ, nó lội xuống trước, úp xì xụp mấy cái đã chộp được con cá trong nằm trong nơm. Bình nhấn nơm xuống sâu, ngẩng mặt nhìn hai đứa tôi cười hì hì, nhún vai, nói:” Đấy, tau nói có sai đâu, cá đầy mương nè. Nhìn tau bắt lên cho coi.”</p>
        <p>Tôi và Sếu ngó xuống, háo hức chờ thằng Bình bắt con cá trong nơm lên, long lồng hồi hộp như bắt vàng. Không mất quá nhiều thời gian, Bình tóm gọn con cá trong tay, đứng thẳng người giơ cao quá đầu, vui mừng nói:</p>
        <p>“ Cá to tổ chảng ah nghen. Mèng ơi.. nay trúng mánh rùi đó hai đứa bây.”</p>
        <p>“ Đâu.. đâu.. thả vô giỏ đi tau xem nó lớn chừng nào?” Thằng Sếu hối..</p>
        <p>Nó quăng giỏ xuống cho thằng Bình bỏ con cá vào, thằng Bình thả con cá trê to bằng cổ tay mình vừa úp được vào giỏ, đưa lại cho thằng Sếu, nói:” Cầm lấy, để tau úp típ. Ờ mà hai đứa bây xuống đây, mò xung quanh vô mấy cái hang góc hốc kìa, xem có tôm cua gì hông, đứng trên đó chi?”</p>
        <p>Lời thằng Bình vừa dứt, bỗng một cơn gió lạnh từ đâu thổi đến làm cho mấy chiếc lá vàng trên cây rơi xuống mặt nước. Tôi thoáng rùng mình ớn lạnh, chẳng hiểu sao tâm chí tôi lại dồn hết vào căn nhà lá bên kia, chứ không có tâm trạng mò cua hay bắt cá. Nhìn dòng nước dục ngòm phía dưới, tôi không sợ bẩn, mà cứ có cảm giác như bên dưới bùn có cái gì đó ma mị, khó tả, đang chờ tôi dưới đó. Nấn ná mãi tôi không dám xuống, thằng Sếu đứng dưới gọi tôi tới mấy lần, mới kéo tôi về thực tại.</p>
        <p>“ Nam.. Nam..xuống đi mầy, làm gì mà đứng đực ra zị cha nội?”</p>
        <p>Tôi cười ngượng, xắn quần tới đầu gối tụt xuống nước. Tiếng tỏm tỏm phía trước làm cả ba chúng tôi chú ý, nhánh cây rủ dưới mặt nước trong bụi rậm khẽ rung rinh lay động. Thằng Bình hất hàm, chỉ tay qua bên đó, nói:” Cá đó, chắc là con cá to nên mới tạo ra tiếng động lớn vậy. Tụi bây ở đây chờ tao.”</p>
        <p>Một mình nó lội về phía trước, vén mấy nhánh cây loà xoà trước mặt, đi thật khẽ sợ đánh động bầy cá, sợ chúng sẽ bơi đi mất. Thằng Bình giơ cao nơm, chụp xuống nước liên tục, một lúc sau nó khựng tay, nhấn nhấn cái nơm sâu xuống bùn, quay lại với tụi tôi.</p>
        <p>“ Lại có cá rồi.. he he he he..”</p>
        <p>Tôi và thằng Sếu nhảy cỡn dưới nước, khen nó giỏi, còn bảo số thằng này sát cá, mới xuống chưa đầy 20p mà đã úp được tới hai con. Úp thêm nửa giờ nữa thì chẳng mấy mà đầy giỏ.</p>
        <p>Trong lúc thằng Bình khom người xuống bắt cá, bên tai tôi nghe tiếng ai đó khóc thút thít, ngày một rõ. Tôi nín thở, cố lắng nghe xem tiếng khóc ấy phát ra từ đầu, mắt đảo xung quanh, đảo tới đảo lui cuối cùng tôi dừng lại ở căn nhà lá. Tôi ngước lên nhìn, thấy đứa bé gái tầm 5-6 tuổi mặc trên người bộ đồ nâu bạc màu, trên tay nó là con búp bê bằng vải, chiếc váy trên người nó đổi màu cáu bẩn đứng trước sân nhìn chúng tôi chằm chằm.</p>
        <p>Tôi vỗ vai thằng Sếu, lắp bắp nói:” Sếu ơi.. mầy nhìn kìa. Bên kia có người.”</p>
        <p>Thằng Sếu hất cánh tay của tôi ra, mắt nó chăm chăm nhìn thằng Bình bắt cá, miệng trả lời tôi:” Tau biểu mầy đừng có nhìn qua bển đó rùi mừ hổng nghe. Nhà đó làm gì có ai ở, nếu mầy thấy gì, thì đó là ma chớ hổng phải người đâu à nhen.” Thấy tôi co rúm người vì sợ, nó biết mình lỡ lời, vỗ vai tôi trấn an:” Trời đất! Tau hù mầy có xíu, mầy đã sợ run như cầy sấy. Thảo nào, đám nhỏ Thương với con Đẹt, nó kêu mầy công tử mặt trắng, quả hông sai.”</p>
        <p>Tôi chưa kịp nói gì, bên kia, thằng Bình đâu mất tiêu, chúng tôi không thấy nó đâu nữa, cái nơm nằm chỏng chơ dưới nước, lật ngược. Thằng Sếu hoảng quá, đưa cho tôi cầm giỏ cá, đưa tay lên miệng, gọi lớn:</p>
        <p>“ Bình ơi Bình.. mầy đâu rùi Bình ơi.. Bình.. ơi.. Bình.. mầy ở đâu, quỡn bầy hổng có zui ah nhen.”</p>
        <p>Mặc thằng Sếu gọi đến khản cổ, bóng dáng thằng Bình vẫn mất dạng. Đôi mắt nó đỏ hoe, quay lại nhìn tôi run rẩy nói:” Thôi chết rùi, thằng Bình, nó bị mẹ con bả bắt đi rầu mầy ơi..” nói xong, nó kéo tôi lên bờ, hối tôi chạy nhanh ra thuyền, đừng quay lại nhìn.</p>
        <p>Tôi níu nó lại, hỏi:” Mầy nói zậy là sao? Hổng lẽ bỏ thằng Bình lại sao bây. Thôi ah.. dù có chiện gì cũng phải tìm nó rùi cùng zìa chớ.”</p>
        <p>Thằng Sếu lôi tôi đi, nó nói như người hụt hơi, giọng sợ hãi:” Không kịp rồi, quay zìa, kêu ngoại mầy ra qua đây cứu nó.”</p>
        <p>Đi được một đoạn, tiếng khóc lại vang vọng bên tai làm tôi tò mò níu thằng Sếu, bước chân chậm chạp hẳn. Tôi ngoảnh lại, thấy hình ảnh đứa bé khi nãy lúc ẩn lúc hiện, đứng sau bụi cây bình bát nhìn hai đứa tôi chằm chằm, đôi mắt đen hun hút không tròng, đen ngòm như có ai đó bị móc đi mất. Khuôn mặt trắng bệch như giấy, trên khoé môi nở nụ cười ma mị.</p>
        <p>Giọng nói ảo não vang vọng, như từ cõi âm ti vọng về, càng làm tôi thêm ớn lạnh.</p>
        <p>“ Ở lại, chơi với tôi.. ở lại chơi với tôi.. ở lại chơi với tôi.. ở lại chơi với tôi.. hí hí hí hí hí hí hí..”</p>
        <p>Dưới mương nước, tôi thấy một người đàn bà đứng quay lưng lại phía chúng tôi, bà ấy đang nắm tóc thằng Bình, nhấn xuống nước. Nó vùng vẫy, giọng lạc đi nghe câu được câu mất.. “ Cứu.. với.. cứu… tôi… cứu.. với..” rồi chìm nghỉm.</p>
        <p>Chân tay tôi khua loạn xạ, gào hét trong đêm miệng luôn gọi tên thằng Bình. “ Bình ơi.. Bình ơi.. đừng đi.. quay lại đây.. ở lại với tụi tao đi mầy..” ba tát mấy cái vô mặt, lay lay gọi tôi dậy, quát mấy câu làm tôi giật mình choàng tỉnh. Hai mắt mở trân trân nhìn lên trần nhà, thở hổn hển mắt đảo tía lia mới nhận ra, mình vừa nằm mơ. Nhưng sao giấc mơ vừa rồi nó giống y chang thật như vậy. Cứ như nó hiện ra ngay trước.</p>
        <p>“ Con gặp ác mộng hay sao mà la lối um sùm lên cả vậy?”</p>
        <p>Tôi nhìn bố gật đầu, kim đồng hồ điểm đúng 12h đêm ngày 14/8 . Ngày mai là rằm tháng 8, chúng tôi sẽ rước đèn đi quanh xóm, dưới ánh trăng đêm. Nghĩ vậy, tôi tạm gác giấc mơ kinh hoàng kia qua một bên, tận hưởng cảm giác hạnh phúc ngay lúc này. Chỉ còn mấy tiếng nữa, tôi sẽ gặp đám thằng Bình, thằng Sếu..</p>
        <p>Hết chương 1</p>
